insert into public.document_guides
  (name, description, countries, when_to_get, where_to_submit, working_hours,
   online_booking, required_docs, cost, waiting_time, instructions, common_mistakes,
   tips, links, important_2026, category, type, pdf_url, online_url)
values
  ('Виза D (рабочая)', 'Национальная виза D — долгосрочная виза Польши для въезда и трудоустройства у конкретного работодателя на основании разрешения на работу или зарегистрированной декларации. Привязана к работодателю и теряет силу при смене места работы.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'За 2-3 месяца до выезда, сразу после получения разрешения на работу или зарегистрированной декларации.', 'Консульство Польши или визовый центр в стране проживания (Беларусь, Россия, Узбекистан, Таджикистан, Казахстан, Кыргызстан, Туркменистан, Азербайджан, Турция и др.). Гражданам ЕС/ЕЭЗ/Швейцарии виза не нужна.', 'Обычно будни, первая половина дня (8:00-13:00), уточняйте по конкретному консульству.', 'Через e-konsulat.gov.pl или сайт визового центра (VFS Global и др.); в странах с высокой нагрузкой возможна запись через электронный жребий.', '["Загранпаспорт (минимум 3 месяца после окончания визы, 2 чистые страницы)", "Визовая анкета", "Фото 35x45 мм", "Разрешение на работу или зарегистрированная декларация", "Медстраховка от 30 000 €", "Подтверждение места проживания в Польше", "Подтверждение финансовой состоятельности", "Квитанция об оплате сбора"]'::jsonb, 'Около 80 € (эквивалент в местной валюте); для владельцев Карты поляка — бесплатно.', '15-30 календарных дней, в 2026 году нередко дольше.', '["Получите разрешение на работу или декларацию от работодателя", "Соберите пакет документов", "Запишитесь через e-Konsulat", "Оплатите сбор", "Подайте документы лично", "Дождитесь решения", "Заберите паспорт с визой", "По приезде в Польшу подайте на карту побыту, если остаётесь дольше срока визы"]'::jsonb, '["Подача без действующего разрешения на работу", "Несоответствие данных анкеты и приглашения работодателя", "Недостаточное покрытие страховки (менее 30 000 €)"]'::jsonb, '["Подавайте сразу после получения разрешения на работу", "Сохраняйте копии всех документов для карты побыту", "Отслеживайте статус через личный кабинет e-Konsulat"]'::jsonb, '["gov.pl (раздел cudzoziemcy)", "e-konsulat.gov.pl"]'::jsonb, 'Для граждан ряда стран СНГ (в первую очередь России) процедура стала избирательнее, сроки выросли, требования к подтверждению трудоустройства ужесточены.', 'визы', 'service', NULL, NULL),
  ('Виза D (студенческая)', 'Долгосрочная виза Польши для въезда и обучения свыше 90 дней на основании справки о зачислении и подтверждения финансовой состоятельности. После въезда оформляется студенческая карта побыту.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'За 2-3 месяца до начала учёбы, сразу после получения письма о зачислении.', 'Консульство Польши в стране проживания (для визовых стран Группы Б); гражданам ЕС/ЕЭЗ виза не нужна.', 'Обычно будни, первая половина дня.', 'Через e-konsulat.gov.pl или сайт визового центра.', '["Загранпаспорт", "Визовая анкета", "Фото 35x45 мм", "Оригинал справки о зачислении", "Подтверждение оплаты обучения (если платно)", "Банковская выписка за 6 месяцев", "Договор аренды или подтверждение общежития", "Медстраховка от 30 000 €", "Квитанция об оплате сбора"]'::jsonb, 'Около 80 €; для владельцев Карты поляка — бесплатно.', '10-30 календарных дней.', '["Получите письмо о зачислении от вуза", "Оформите страховку и финансовые документы", "Соберите пакет документов (заложите время на переводы и апостиль)", "Запишитесь через e-Konsulat", "Оплатите сбор", "Подайте документы лично", "Дождитесь решения", "По прилёте зарегистрируйтесь по месту жительства и подайте на карту побыту при необходимости"]'::jsonb, '["Неполная/устаревшая банковская выписка без движения средств за 6 месяцев", "Страховка не соответствует требованиям по покрытию/сроку", "Ошибки в анкете относительно данных справки о зачислении"]'::jsonb, '["Запрашивайте справку о зачислении заранее — это самый долгий этап", "Делайте выписку с движением средств, а не просто справку об остатке", "Сохраняйте оригиналы и заверенные копии для карты побыту"]'::jsonb, '["gov.pl (раздел cudzoziemcy)", "e-konsulat.gov.pl"]'::jsonb, 'Консульства строже проверяют финансовую состоятельность, корректность страховки и подтверждение проживания.', 'визы', 'service', NULL, NULL),
  ('Виза D (бизнес)', 'Долгосрочная виза Польши для собственников бизнеса, инвесторов и управленцев, ведущих или планирующих предпринимательскую деятельность в Польше. Не даёт права работать по найму у стороннего работодателя.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'За 2-3 месяца до поездки, после регистрации бизнеса или получения приглашения от польских партнёров.', 'Консульство Польши или визовый центр (в части стран, напр. Беларусь, деловые визы принимаются только через визовые центры).', 'Обычно будни, первая половина дня.', 'Через e-konsulat.gov.pl или визовый центр.', '["Загранпаспорт", "Визовая анкета", "Фото 35x45 мм", "Нотариально заверенное приглашение от партнёра либо выписка из KRS/CEIDG", "Банковская выписка за 6 месяцев (личная или компании)", "Подтверждение проживания в Польше", "Медстраховка от 30 000 € на срок от 6 месяцев", "Внутренний паспорт", "Квитанция об оплате сбора"]'::jsonb, 'Около 80 €; для владельцев Карты поляка — бесплатно.', '15-30 календарных дней.', '["Зарегистрируйте бизнес или получите заверенное приглашение партнёра", "Подготовьте финансовые документы", "Оформите страховку у аккредитованного страховщика", "Соберите пакет документов", "Запишитесь и оплатите сбор", "Подайте документы лично", "Дождитесь решения и заберите паспорт"]'::jsonb, '["Приглашение от компании не заверено нотариально", "Недостаточное движение средств по счёту", "Путаница между бизнес-визой и рабочей визой"]'::jsonb, '["Уточняйте заранее, принимает ли консульство бизнес-визы напрямую или только через визовый центр", "Готовьте нотариальное приглашение заранее", "Держите личные и корпоративные выписки одновременно"]'::jsonb, '["gov.pl (раздел cudzoziemcy)", "e-konsulat.gov.pl"]'::jsonb, 'В ряде стран (напр. Беларусь) приём документов передан визовым центрам; консульства внимательнее проверяют реальность деловых отношений.', 'визы', 'service', NULL, NULL),
  ('Виза D (воссоединение семьи)', 'Долгосрочная виза Польши для супругов, несовершеннолетних детей и в отдельных случаях других родственников иностранца, легально проживающего в Польше. Выдаётся на основании подтверждённого родства и возможности содержать семью.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Как только приглашающий член семьи получил легальный статус и готов подтвердить доход и жильё.', 'Консульство Польши по месту проживания; либо заявление в воеводское управление на территории Польши, если заявитель уже там на другой визе.', 'Обычно будни, первая половина дня.', 'Через e-konsulat.gov.pl или визовый центр.', '["Загранпаспорт", "Визовая анкета", "Фото 35x45 мм", "Свидетельство о браке/рождении с присяжным переводом", "Копия документа о легальном статусе приглашающего", "Подтверждение дохода приглашающей стороны", "Подтверждение жилья в Польше", "Медстраховка от 30 000 €", "Квитанция об оплате сбора"]'::jsonb, 'Около 80 €; для несовершеннолетних сбор может быть снижен; для владельцев Карты поляка — бесплатно.', '15-30 календарных дней, при проверке родства может быть дольше.', '["Убедитесь в легальном статусе приглашающего члена семьи", "Легализуйте и переведите документы о родстве", "Подготовьте подтверждение дохода и жилья", "Соберите пакет документов", "Запишитесь и оплатите сбор", "Подайте документы лично", "По приезде зарегистрируйтесь и подайте на карту побыту при необходимости"]'::jsonb, '["Отсутствие присяжного перевода свидетельства о браке/рождении", "Недостаточное подтверждение дохода приглашающей стороны", "Устаревший документ о статусе приглашающего"]'::jsonb, '["Начинайте легализацию документов о родстве заранее", "Если приглашающий — гражданин ЕС/Польши, уточните упрощённую процедуру", "Держите оригиналы документов о родстве под рукой"]'::jsonb, '["gov.pl (раздел cudzoziemcy)", "e-konsulat.gov.pl"]'::jsonb, 'Требуется чёткое подтверждение дохода и жилья; для приглашающих-граждан ЕС/Польши действуют более мягкие правила.', 'визы', 'service', NULL, NULL),
  ('Виза D (гуманитарная, D21)', 'Долгосрочная виза, выдаваемая по гуманитарным соображениям, из интересов государства или в рамках международных обязательств Польши (болезнь/смерть родственника, политическое давление, ограниченные визовые каналы). Решение принимается индивидуально.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'При наступлении конкретного экстренного обстоятельства либо когда стандартные визовые каналы недоступны.', 'Консульство Польши по месту проживания; порядок для этой категории часто отличается от стандартного.', 'Может отличаться от стандартного визового окна — уточняйте у консульства.', 'Стандартная система e-Konsulat может не подходить — часто обращение напрямую в консульский отдел.', '["Загранпаспорт", "Визовая анкета", "Фото 35x45 мм", "Документы, подтверждающие гуманитарное основание (медсправки, свидетельство о смерти, доказательства угрозы)", "Медстраховка (в экстренных случаях может не требоваться на этапе подачи)"]'::jsonb, 'В отдельных гуманитарных случаях сбор может быть снижен или отсутствовать.', 'От нескольких дней в экстренных случаях до стандартных 15-30 дней.', '["Задокументируйте гуманитарное основание", "Соберите подтверждающие документы", "Свяжитесь с консульством для уточнения порядка подачи именно для этой категории", "Подайте документы", "Дождитесь решения"]'::jsonb, '["Недостаточно убедительное обоснование гуманитарного характера", "Попытка использовать категорию как замену стандартной визе без реальных оснований", "Обращение по общей системе записи вместо предусмотренного порядка"]'::jsonb, '["Заранее соберите официальные медицинские/семейные подтверждающие документы", "Свяжитесь с консульством напрямую по официальным контактам", "Уточните, какие категории обстоятельств консульство считает гуманитарными"]'::jsonb, '["gov.pl (раздел cudzoziemcy)", "сайт посольства/консульства Польши в вашей стране"]'::jsonb, 'Одна из немногих доступных категорий для граждан России, так как консульства приостановили приём большинства других заявлений; решение индивидуально без гарантий.', 'визы', 'service', NULL, NULL),
  ('Временная защита (украинцы)', 'Правовой статус (PESEL UKR), введённый ЕС для граждан Украины и части других лиц, вынужденно покинувших страну из-за войны. Даёт право на проживание, работу, медпомощь и соцвыплаты без обычной визы/ВНЖ. Продлён Советом ЕС до 4 марта 2027 года.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после пересечения границы Польши; при въезде после 5 марта 2026 года — заявление в течение 30 дней.', 'Любое управление города/гмины (urząd miasta/gminy) на территории Польши, не обязательно по месту проживания.', 'Обычно будни 8:00-16:00/17:00, зависит от управления.', 'В большинстве городов запись через сайт управления (система kolejka/rezerwacja).', '["Действительный загранпаспорт", "Фотография", "Заполненная анкета", "Для ранее присвоенного статуса по декларации без документа — до 31.08.2026 нужно лично подтвердить личность"]'::jsonb, 'Бесплатно.', 'Как правило, в день обращения.', '["Определите ближайшее управление города/гмины", "Запишитесь онлайн при необходимости", "Придите с паспортом", "Заполните анкету", "Сдайте биометрию", "Получите подтверждение PESEL UKR", "При статусе по декларации — подтвердите личность до 31.08.2026"]'::jsonb, '["Пропуск 30-дневного срока подачи после пересечения границы", "Выезд из Польши более чем на 30 дней подряд", "Неподтверждение личности документом до дедлайна"]'::jsonb, '["С 5 марта 2026 действует общий закон о защите иностранцев вместо спецзакона", "Рассматривайте переход на карту CUKR как переходный механизм", "Упрощённая процедура трудоустройства по уведомлению сохраняется"]'::jsonb, '["gov.pl", "UNHCR Poland", "сайт местного управления"]'::jsonb, 'Статус продлён до 4 марта 2027 года; с 4 марта 2026 применяется общий закон об иностранцах вместо спецзакона.', 'легализация', 'service', NULL, NULL),
  ('Шенгенская виза', 'Краткосрочная виза типа C для пребывания в Шенгенской зоне (включая Польшу) до 90 дней в любые 180 дней: туризм, деловые поездки, визиты к родственникам, краткосрочное обучение/лечение.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не ранее чем за 6 месяцев и не позднее чем за 15 дней до поездки.', 'Консульство Польши или визовый центр (VFS Global и аналоги) в стране проживания.', 'Обычно будни, первая половина дня.', 'Обязательна через e-konsulat.gov.pl или сайт визового центра.', '["Загранпаспорт (минимум 3 месяца после поездки, 2 чистые страницы, выдан не более 10 лет назад)", "Анкета", "Фото 35x45 мм", "Медстраховка от 30 000 €", "Подтверждение цели поездки", "Подтверждение финансовой состоятельности", "Подтверждение обратного билета"]'::jsonb, '90 € для взрослых, 45 € для детей 6-12 лет, бесплатно до 6 лет; плюс сервисный сбор визового центра 30-50 €.', 'Около 15 дней, в отдельных случаях 30-60 дней.', '["Определите цель и сроки поездки", "Запишитесь онлайн", "Соберите документы", "Оплатите сборы", "Сдайте биометрию (при первой подаче)", "Дождитесь решения", "Заберите паспорт"]'::jsonb, '["Недостаточное подтверждение финансовой состоятельности и цели поездки", "Подача слишком рано (>6 мес.) или слишком поздно (<15 дней)", "Недостаточное покрытие страховки (<30 000 €)"]'::jsonb, '["Записывайтесь заранее в высокий сезон", "Для безвизовых стран Группы Г с 2026 действует ETIAS вместо визы", "Подавайте в консульство страны, где будете дольше всего"]'::jsonb, '["gov.pl", "e-konsulat.gov.pl"]'::jsonb, 'Стоимость визы C повышена до 90 €; усилены требования к цифровой подаче; для ранее безвизовых стран добавлено обязательное ETIAS.', 'визы', 'service', NULL, NULL),
  ('Транзитная виза (Виза типа A)', 'Специальная виза для нахождения только в международной транзитной зоне польского аэропорта при пересадке, без пересечения границы. Требуется гражданам стран из общего перечня ЕС (Афганистан, Бангладеш, ДР Конго, Эритрея, Эфиопия, Гана, Иран, Ирак, Нигерия, Пакистан, Сомали, Шри-Ланка, Сирия); отдельно проверяйте статус Армении.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не ранее 6 месяцев и не позднее 15 дней до даты транзита.', 'Консульство Польши или визовый центр в стране проживания.', 'Зависит от консульства.', 'Обязательна через e-Konsulat или визовый центр.', '["Загранпаспорт (минимум 3 месяца после транзита)", "Анкета", "Фото 35x45 мм", "Подтверждённый билет на рейс вылета из транзитной зоны", "Виза в страну конечного назначения (если нужна)"]'::jsonb, 'Около 80-90 € (не возвращается независимо от решения).', 'До 15 дней, в отдельных случаях 30-45 дней.', '["Проверьте, входит ли ваше гражданство в перечень", "Запишитесь через e-Konsulat", "Соберите документы, включая подтверждённый билет", "Оплатите сбор", "Сдайте документы и биометрию", "Дождитесь решения"]'::jsonb, '["Предположение, что виза не нужна, без проверки актуального списка", "Отсутствие подтверждённого билета на вылет из транзитной зоны", "Попытка выйти из транзитной зоны"]'::jsonb, '["При наличии действующей шенгенской/американской/канадской визы или ВНЖ ЕЭЗ виза A обычно не требуется", "Уточняйте требования для каждого аэропорта транзита отдельно", "Планируйте подачу заранее"]'::jsonb, '["gov.pl", "e-konsulat.gov.pl"]'::jsonb, 'Список стран пересматривается периодически — проверяйте актуальную версию перед поездкой.', 'визы', 'service', NULL, NULL),
  ('Регистрация адреса (мелдунок)', 'Zameldowanie — обязательная регистрация места проживания в Польше для граждан и иностранцев; требуется для получения PESEL, карты побыту, записи детей в школу и др.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Граждане ЕС/ЕЭЗ/Швейцарии — не позднее 30 дня с прибытия; остальные — не позднее 4 дня при пребывании свыше 30 дней.', 'Управление города/гмины (urząd miasta/gminy) по месту жительства, отдел ewidencji ludności.', 'Будни, около 7:30/8:00-15:30/17:00.', 'С 1 января 2026 онлайн-подача только через e-Doręczenia; личная подача доступна без записи или по записи.', '["Паспорт (для ЕС/ЕЭЗ) или паспорт+виза/карта побыту (для остальных)", "Формуляр регистрации", "Документ о праве пользования жильём (договор аренды, согласие собственника, księga wieczysta)", "Письменное согласие собственника, если оформляет не он"]'::jsonb, 'Бесплатно; справка о временном пребывании — 17 злотых.', 'Обычно в день обращения.', '["Соберите документы", "Получите согласие собственника, если нужно", "Заполните формуляр", "Подайте лично или через e-Doręczenia", "Получите отметку о регистрации"]'::jsonb, '["Пропуск 4-дневного срока регистрации", "Отсутствие письменного согласия собственника", "Попытка онлайн-регистрации без e-Doręczenia"]'::jsonb, '["Можно оформить через представителя по доверенности", "Нельзя иметь два постоянных или два временных мелдунка одновременно", "При смене жилья можно подать выписку и новую регистрацию одновременно"]'::jsonb, '["сайт вашей гмины", "gov.pl (Zameldowanie)"]'::jsonb, 'С 1 января 2026 онлайн-подача требует активного адреса e-Doręczenia — одного Profil Zaufany недостаточно.', 'легализация', 'service', NULL, NULL),
  ('PESEL обычный', 'Одиннадцатизначный идентификационный номер в польском реестре населения. Нужен для Profil Zaufany, декларации PIT, легального трудоустройства и подписания договоров.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Как можно раньше после регистрации по месту жительства или сразу при необходимости (работа, ZUS, налоговая, пособия).', 'При наличии мелдунка присваивается автоматически; без мелдунка — заявление в любое управление города/гмины.', 'Зависит от управления.', 'Рекомендуется предварительная запись; с 1 января 2026 граждане не из ЕС/ЕЭЗ/Швейцарии обязаны подавать лично.', '["Загранпаспорт или иной документ личности", "Заполненное и подписанное заявление", "Документы, подтверждающие данные заявления", "Указание правового основания получения PESEL", "Нотариально заверенный перевод иностранных документов"]'::jsonb, 'Присвоение — бесплатно; справка — 17 злотых; доверенность (для ЕС/ЕЭЗ) — 17 злотых.', 'В день обращения или несколько рабочих дней.', '["Проверьте, есть ли уже мелдунек (тогда PESEL присвоят автоматически)", "Определите правовое основание", "Заполните заявление", "Запишитесь при необходимости", "Подайте лично (обязательно для не-ЕС с 2026)", "Получите номер PESEL", "При необходимости закажите справку"]'::jsonb, '["Не указано правовое основание получения PESEL", "Попытка подать через представителя, будучи гражданином не ЕС/ЕЭЗ/Швейцарии", "Путаница между мелдунком и PESEL"]'::jsonb, '["Проще всего получить PESEL одновременно с мелдунком", "Уточните точную формулировку основания заранее", "Закажите справку о присвоении сразу — пригодится для Profil Zaufany"]'::jsonb, '["gov.pl (Uzyskaj numer PESEL)"]'::jsonb, 'С 1 января 2026 граждане не из ЕС/ЕЭЗ/Швейцарии обязаны подавать заявление лично.', 'легализация', 'service', NULL, NULL),
  ('PESEL со статусом UKR', 'PESEL для граждан Украины и части членов их семей, легально прибывших в связи с военными действиями с 24.02.2022. Даёт доступ к правам временной защиты.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В течение 30 дней с момента пересечения границы Польши.', 'Любое управление города/гмины на территории Польши.', 'Зависит от управления.', 'В большинстве городов рекомендуется предварительная запись.', '["Заявление формы PL-UKR", "Действительный загранпаспорт или иной документ личности", "Фотография", "Для статуса, ранее присвоенного по декларации — до 31.08.2026 личное подтверждение личности документом"]'::jsonb, 'Бесплатно.', 'Как правило, в день обращения.', '["Определите удобное управление гмины", "Запишитесь онлайн при необходимости", "Заполните форму PL-UKR", "Придите лично с паспортом", "Сдайте биометрию", "Получите PESEL UKR", "Подтвердите личность документом до 31.08.2026, если статус был по декларации"]'::jsonb, '["Пропуск 30-дневного срока подачи", "Выезд из Польши более чем на 30 дней", "Игнорирование требования подтвердить личность документом до 31.08.2026"]'::jsonb, '["С 5 марта 2026 справки о временной защите больше не выдаются — основной документ учёта это PESEL UKR", "Рассмотрите карту CUKR как более стабильную альтернативу", "При утере справки о временной защите обратитесь за новым PESEL UKR"]'::jsonb, '["gov.pl", "UNHCR Poland", "сайт местного управления"]'::jsonb, 'С 4 марта 2026 применяется закон о защите иностранцев вместо спецзакона; статус продлён до 4 марта 2027 года; введена карта CUKR.', 'легализация', 'service', NULL, NULL),
  ('Карта побыту, временная (работа)', 'Единое разрешение на временное проживание и работу у конкретного работодателя (до 3 лет). По результату выдаётся пластиковая карта побыту.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее последнего дня легального пребывания в Польше.', 'Исключительно через портал MOS (mos.cudzoziemcy.gov.pl); рассматривает воевода по месту проживания.', 'Личная явка по вызову воеводы — уточняйте на сайте управления воеводства.', 'Регистрация в MOS через Profil Zaufany или квалифицированную подпись; нужен e-Doręczenia.', '["Загранпаспорт", "Фотография", "Приложение №1, заполненное работодателем в MOS", "Подтверждение оплаты гербового сбора", "Подтверждение оплаты за карту"]'::jsonb, 'Гербовый сбор 340 злотых (пребывание) или 440 злотых (пребывание и работа); карта — 100 злотых; скидка 50% для отдельных категорий.', 'Официально от 60 дней, на практике в крупных городах — месяцы, иногда более года.', '["Получите PESEL и Profil Zaufany", "Заведите e-Doręczenia", "Работодатель заполняет Приложение №1 в MOS", "Оплатите гербовый сбор", "Подайте заявление не позднее срока легального пребывания", "Явитесь на биометрию по вызову", "После решения оплатите 100 злотых и заберите карту"]'::jsonb, '["Подача после истечения срока легального пребывания", "Подача без заполненного работодателем Приложения №1", "Игнорирование вызова на биометрию"]'::jsonb, '["Подавайте максимально заранее — реальные сроки превышают официальные", "Минимальная зарплата в договоре не может быть ниже 4806 злотых брутто (2026)", "Сохраняйте подтверждение подачи (zaświadczenie)"]'::jsonb, '["mos.cudzoziemcy.gov.pl"]'::jsonb, 'С 27 апреля 2026 заявление подаётся только через MOS 2.0; бумажные заявления после этой даты не рассматриваются.', 'легализация', 'service', NULL, NULL),
  ('Карта побыту временная (учёба)', 'Подтверждает право иностранца легально находиться в Польше на срок очного обучения дольше 3 месяцев.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее последнего дня легального пребывания.', 'Через MOS (mos.cudzoziemcy.gov.pl); обращение в Urząd Wojewódzki по месту жительства (Варшава, Краков, Вроцлав, Гданьск, Познань, Лодзь, Щецин, Люблин, Катовице).', 'Уточняйте на сайте конкретного Urząd Wojewódzki.', 'Через MOS с PESEL и Profil Zaufany.', '["Загранпаспорт", "Справка из университета о зачислении/продолжении обучения", "Подтверждение оплаты обучения или освобождения от неё", "Подтверждение медстраховки", "Подтверждение финансовых средств на весь период (не более 3 лет)", "Подтверждение жилья", "Фотографии"]'::jsonb, 'Пошлина 340 злотых; выдача карты 50-100 злотых; доверенность 17 злотых.', '1-3 месяца, на практике может доходить до 6 месяцев и более.', '["Получите справку от вуза", "Оформите страховку и подтверждение средств", "Создайте Profil Zaufany и аккаунт в MOS", "Подайте заявление не позднее срока легальности", "Оплатите пошлину 340 злотых", "Явитесь на биометрию", "После решения оплатите 50-100 злотых и заберите карту"]'::jsonb, '["Подача после истечения легального пребывания", "Недостаточное подтверждение финансовых средств", "Незаверенный перевод документов"]'::jsonb, '["Подавайте за 1-2 месяца до окончания текущего статуса", "Сохраняйте номер дела (numer sprawy)", "Заведите Profil Zaufany заранее"]'::jsonb, '["mos.cudzoziemcy.gov.pl", "gov.pl/web/profilzaufany"]'::jsonb, 'С 27 апреля 2026 действует обновлённая система MOS; старые аккаунты не перенесены.', 'легализация', 'service', NULL, NULL),
  ('Карта побыту временная (бизнес)', 'Подтверждает право иностранца находиться в Польше, если основная цель — ведение собственной предпринимательской деятельности (ИП, участие в правлении, проку́ра).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее последнего дня легального пребывания.', 'Через MOS; рассматривает Urząd Wojewódzki по месту ведения бизнеса.', 'Уточняйте на сайте Urząd Wojewódzki.', 'Через MOS с PESEL и Profil Zaufany.', '["Загранпаспорт", "Выписка из CEIDG/KRS", "Выписка со счёта фирмы", "Справка из ZUS об отсутствии задолженности", "Справка из налоговой", "Финансовые документы фирмы", "Присяжный перевод иностранных документов"]'::jsonb, 'Пошлина 340 злотых; карта 50 злотых; доверенность 17 злотых.', 'Официально до 60 дней, на практике может занимать дольше.', '["Зарегистрируйте бизнес (ИП или ООО)", "Соберите финансовые документы фирмы", "Создайте Profil Zaufany и аккаунт MOS", "Подайте заявление", "Оплатите пошлину", "Явитесь на биометрию", "После решения оплатите карту и заберите её"]'::jsonb, '["Неполный пакет финансовых документов фирмы", "Подача в последний момент без учёта долгого срока рассмотрения", "Отсутствие перевода документов не на польском"]'::jsonb, '["Приложите максимум подтверждающих документов сразу", "Подавайте за 2-3 месяца до истечения легальности", "Сохраняйте номер дела"]'::jsonb, '["mos.cudzoziemcy.gov.pl"]'::jsonb, 'С 27 апреля 2026 подача только через обновлённый MOS; действуют новые распоряжения МВД 2025-2026.', 'легализация', 'service', NULL, NULL),
  ('Карта побыту временная (семья)', 'Подтверждает право иностранца находиться в Польше как члена семьи гражданина Польши либо иностранца, легально проживающего в стране.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее последнего дня легального пребывания; заявитель подаёт лично сам.', 'Через MOS; рассматривает Urząd Wojewódzki по месту пребывания.', 'Уточняйте на сайте управления.', 'Через MOS с Profil Zaufany.', '["Загранпаспорт", "Документы, подтверждающие родство, с присяжным переводом", "Письменное согласие члена семьи за границей (если применимо)", "Подтверждение дохода (свыше 1010 зл нетто одиноким/823 зл на члена семьи)", "Подтверждение жилья", "Медстраховка", "4 фотографии"]'::jsonb, 'Пошлина зависит от основания; карта — около 100 злотых.', 'От 1 до нескольких месяцев в зависимости от обстоятельств дела.', '["Соберите и переведите документы о родстве", "Создайте Profil Zaufany и аккаунт MOS", "Заполните и лично подпишите заявление (не через представителя)", "Оплатите пошлину", "Подайте лично", "Сохраните справку о подаче", "После решения оплатите карту"]'::jsonb, '["Подача представителем/супругом вместо самого иностранца", "Отсутствие присяжного перевода документов о родстве", "Недостаточное подтверждение дохода или жилья"]'::jsonb, '["Справка о подаче подтверждает легальность пребывания до решения", "Подавайте максимально полный пакет сразу", "Проверяйте статус дела в MOS"]'::jsonb, '["mos.cudzoziemcy.gov.pl"]'::jsonb, 'С 27 апреля 2026 бумажные заявления после 26.04.2026 не рассматриваются; старые аккаунты MOS не перенесены.', 'легализация', 'service', NULL, NULL),
  ('Карта побыту постоянная', 'Бессрочное разрешение на пребывание в Польше; карта, подтверждающая его, действительна 10 лет. Даёт право работать без разрешения и является шагом к гражданству.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Когда выполнены условия (стаж проживания, брак с гражданином Польши, происхождение/Karta Polaka).', 'Через MOS; личный визит в Urząd Wojewódzki для биометрии.', 'Уточняйте на сайте управления.', 'Через MOS, запись не требуется для заполнения заявления, только для визита на биометрию.', '["Загранпаспорт (все страницы отсканированы)", "Биометрическое фото", "Документы, подтверждающие основание (Karta Polaka, свидетельство о браке и др.)", "Подтверждение оплаты пошлины"]'::jsonb, 'Пошлина 640 злотых; карта 50-100 злотых; бесплатно для беженцев и владельцев Karta Polaka.', 'Индивидуально, зависит от обстоятельств и загруженности управления.', '["Создайте Profil Zaufany и аккаунт MOS", "Заполните заявление, приложите сканы и оплатите 640 злотых", "Подпишите и отправьте, сохраните UPO", "Дождитесь вызова на биометрию", "После решения оплатите карту и заберите её (действует 10 лет)"]'::jsonb, '["Отсутствие сохранённого UPO после подачи", "Подача с недостаточно подтверждённым основанием", "Неявка с оригиналом паспорта на визит"]'::jsonb, '["Подача и доступ к MOS бесплатны", "Заполнение можно приостановить и продолжить позже", "Владельцы Karta Polaka и получившие убежище освобождены от пошлины"]'::jsonb, '["mos.cudzoziemcy.gov.pl", "gov.pl/web/profilzaufany"]'::jsonb, 'С 27 апреля 2026 подача только через новую MOS; старая версия отключена 17.04.2026, данные не перенесены.', 'легализация', 'service', NULL, NULL),
  ('Карта долгосрочного резидента ЕС', 'Бессрочное разрешение на пребывание после минимум 5 лет легального проживания в Польше; дополнительно даёт возможность переезда и работы в другой стране ЕС. Требует подтверждения знания польского языка.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После не менее 5 лет непрерывного легального пребывания в Польше.', 'Через MOS; личный визит в Urząd Wojewódzki для биометрии.', 'Уточняйте на сайте управления.', 'Через MOS с Profil Zaufany.', '["Загранпаспорт", "Биометрическое фото", "Документ о праве на жильё", "Подтверждение стабильного дохода за 5 лет", "Медстраховка", "Сертификат знания польского языка не ниже B1", "Подтверждение оплаты пошлины 640 злотых"]'::jsonb, 'Пошлина 640 злотых; карта 100 злотых (50 для детей до 16 лет).', 'Официально до 6 месяцев.', '["Убедитесь в выполнении 5-летнего срока", "Получите сертификат B1", "Создайте Profil Zaufany и аккаунт MOS", "Подайте заявление, оплатите пошлину", "Сохраните UPO", "Явитесь на биометрию", "После решения в течение 30 дней подайте на карту и оплатите 100 злотых"]'::jsonb, '["Ошибочный расчёт 5-летнего срока", "Устаревший документ об уровне польского языка", "Пропуск 30-дневного срока подачи на карту после решения"]'::jsonb, '["Пребывание легально с момента подачи до решения при правильной подаче", "Проверьте требования к сертификату заранее — правила ужесточаются с середины 2026", "Статус ЕС даёт возможность переезда в другую страну ЕС"]'::jsonb, '["mos.cudzoziemcy.gov.pl", "gov.pl/web/profilzaufany"]'::jsonb, 'С 27 апреля 2026 подача только электронно; с 1 июля 2026 свидетельство школы policealna не признаётся как подтверждение языка — нужен сертификат B1.', 'легализация', 'service', NULL, NULL),
  ('Разрешение на работу тип A', 'Официальный документ, дающий иностранцу право работать у польского работодателя. Подаёт работодатель, а не сам иностранец, в воеводское управление.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До начала работы; подавать за 2-4 месяца до планируемой даты начала.', 'Работодатель через praca.gov.pl в воеводское управление по месту регистрации компании.', 'Уточняйте на сайте управления.', 'Через praca.gov.pl; в Мазовецком воеводстве доступен координированный режим.', '["Заявление о выдаче разрешения", "Заявление о несудимости", "Договор/проект договора с иностранцем", "Копия паспорта", "Документы о квалификации (для регулируемых профессий)", "Подтверждение оплаты пошлины", "Документы о регистрации работодателя"]'::jsonb, '200 злотых (до 3 месяцев) или 400 злотых (свыше 3 месяцев).', 'Официально до 1 месяца, на практике 1-4 месяца в зависимости от воеводства.', '["Убедитесь в соответствии зарплаты минимальным требованиям", "Подготовьте пакет документов", "Подайте заявление через praca.gov.pl", "Оплатите пошлину", "Дождитесь решения воеводы", "После решения работодатель передаёт оригинал", "Если за границей — оформите визу D, цель 06"]'::jsonb, '["Подача заявления самим иностранцем вместо работодателя", "Зарплата ниже минимальных требований", "Позднее обращение без учёта реальных сроков рассмотрения"]'::jsonb, '["Проверьте право на упрощённую процедуру oświadczenie для граждан Армении/Украины/Беларуси/Молдовы/Грузии", "В Мазовецком воеводстве выбирайте координированный режим", "Подавайте за 2-4 месяца заранее"]'::jsonb, '["praca.gov.pl", "biznes.gov.pl"]'::jsonb, 'С 1 июня 2025 отменён тест рынка труда для типа A; минимальная зарплата с 2026 — 4806 злотых брутто/мес.', 'работа', 'service', NULL, NULL),
  ('Разрешение на работу тип B', 'Касается иностранцев, занимающих должность в органах управления юрлица (президент/член правления, прокурист) или комплементария, если функция длится более 6 месяцев из 12.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До начала исполнения функции, если срок превысит 6 из 12 месяцев.', 'Компания через praca.gov.pl или лично в воеводское управление по месту регистрации юрлица.', 'Уточняйте на сайте управления.', 'Через praca.gov.pl, требуется предварительная запись в большинстве управлений.', '["Заявление о выдаче разрешения типа B", "Заявление о несудимости", "Выписка из КРС и протокол о назначении", "Копия паспорта", "Финансовая документация компании", "Присяжные переводы иностранных документов"]'::jsonb, '200 злотых (до 3 месяцев) или 400 злотых (свыше 3 месяцев).', 'Официально до 1 месяца, на практике 2-4 месяца.', '["Убедитесь, что срок функции превысит 6 из 12 месяцев", "Подготовьте документы о назначении в правление", "Подайте заявление через praca.gov.pl", "Оплатите пошлину", "Дождитесь решения", "Оформите визу D при необходимости"]'::jsonb, '["Ошибочное мнение, что владение долей освобождает от разрешения", "Попытка обойти требование сменой правления каждые 6 месяцев", "Неполный пакет финансовых документов"]'::jsonb, '["Если функция короче 6 из 12 месяцев, разрешение может не понадобиться", "Готовьте выписку из КРС и протокол заранее", "Рассмотрите привлечение юриста — процедура сложнее типа A"]'::jsonb, '["praca.gov.pl", "biznes.gov.pl"]'::jsonb, 'Выдаётся на срок не более 3 лет (до 5 лет при штате свыше 25 сотрудников); с 1 июня 2026 уведомления только электронно.', 'работа', 'service', NULL, NULL),
  ('Разрешение на работу тип C', 'Оформляется для иностранца у зарубежного работодателя, делегируемого в Польшу на срок более 30 дней в году в отделение, филиал или связанную компанию.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До начала работы в Польше, если делегирование превысит 30 дней в году.', 'Зарубежный работодатель через praca.gov.pl в воеводское управление по месту фактической работы иностранца.', 'Уточняйте на сайте управления.', 'Полностью электронная подача через praca.gov.pl.', '["Электронное заявление", "Заявление о несудимости", "Документы о связи между компаниями", "Копия всех страниц паспорта", "Документы об условиях делегирования и зарплате", "Данные представителя в Польше", "Присяжные переводы"]'::jsonb, '200 злотых (до 3 месяцев) или 400 злотых (свыше 3 месяцев).', 'Официально до 1 месяца, на практике от 1 до нескольких месяцев.', '["Убедитесь, что делегирование превысит 30 дней в году", "Подготовьте документы о связи компаний", "Назначьте представителя в Польше", "Подайте заявление через praca.gov.pl", "Убедитесь в зарплате не ниже 70% средней по воеводству", "Оплатите пошлину", "Дождитесь решения", "Оформите визу D при необходимости"]'::jsonb, '["Невозможность подтвердить связь между зарубежным работодателем и польским отделением", "Заниженная зарплата ниже 70% средней по воеводству", "Отсутствие назначенного представителя в Польше"]'::jsonb, '["Заранее подготовьте документы о корпоративной связи компаний", "Назначьте представителя заблаговременно", "Проверьте актуальный уровень средней зарплаты в нужном воеводстве"]'::jsonb, '["praca.gov.pl", "biznes.gov.pl"]'::jsonb, 'С 1 июня 2025 все заявления только электронно; к заявлению прикладываются сканы всех страниц паспорта.', 'работа', 'service', NULL, NULL),
  ('Разрешение на работу тип D', 'Для иностранца у зарубежного работодателя без отделения/филиала в Польше, делегируемого для разовой экспортной услуги временного характера.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До начала оказания услуги, обычно за 1-2 месяца.', 'Зарубежный работодатель через praca.gov.pl в воеводское управление по месту оказания услуги.', 'Уточняйте на сайте управления.', 'Полностью электронная подача.', '["Электронное заявление", "Заявление о несудимости (не старше 30 дней)", "Договор об оказании услуги в Польше", "Документы об обстоятельствах делегирования", "Копия всех страниц паспорта", "Документы о квалификации для регулируемых профессий"]'::jsonb, '800 злотых — значительно выше типов A/B/C.', 'Официально до 1 месяца, на практике может отличаться.', '["Убедитесь, что у компании нет организованной формы деятельности в Польше", "Подготовьте договор об оказании услуги", "Соберите документы об обстоятельствах делегирования", "Подайте заявление через praca.gov.pl", "Оплатите 800 злотых", "Дождитесь решения", "Оформите титул пребывания для работы в Польше"]'::jsonb, '["Подача типа D, когда у компании уже есть филиал в Польше (нужен тип C)", "Отсутствие/неполнота договора об оказании услуги", "Путаница между разовой услугой (D) и постоянным делегированием (C)"]'::jsonb, '["Подготовьте договор в окончательном виде заранее", "Услуга должна быть временной и разовой", "Для командировок до 3 месяцев проверьте безвизовый режим для страны иностранца"]'::jsonb, '["praca.gov.pl", "biznes.gov.pl"]'::jsonb, 'Госпошлина 800 злотых; ключевое условие — у работодателя нет организованной формы деятельности в Польше.', 'работа', 'service', NULL, NULL),
  ('Заявление о намерении доверить работу', 'Упрощённая процедура трудоустройства без полноценного разрешения на работу, доступная только гражданам 5 стран: Армении, Беларуси, Грузии, Молдовы и Украины (с оговоркой). Подаёт работодатель в повятовый уженд працы, максимум на 24 месяца.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До того, как иностранец фактически приступит к работе.', 'Powiatowy Urząd Pracy по месту нахождения фирмы, исключительно через portal praca.gov.pl.', 'Будни, около 7:30/8:00-15:30/16:00.', 'Через praca.gov.pl, отдельная запись не нужна.', '["Заполненное заявление на praca.gov.pl", "Данные работодателя (NIP, REGON, PKD)", "Скан всех страниц загранпаспорта иностранца", "Заявление работодателя о несудимости", "Подтверждение оплаты сбора"]'::jsonb, '400 злотых за заявление (с 1 декабря 2025); ранее было 100 злотых.', '7 рабочих дней при полном пакете; до 30 дней при разъяснительном производстве.', '["Убедитесь, что работник — гражданин одной из 5 стран и должность не исключена", "Зарегистрируйтесь на praca.gov.pl", "Заполните форму и оплатите 400 злотых", "Приложите скан паспорта и заявление о несудимости", "Подпишите и отправьте", "Дождитесь внесения в реестр (обычно 7 дней)", "Работник может приступать только после подтверждения"]'::jsonb, '["Разрешение приступить к работе до внесения заявления в реестр", "Неполный пакет документов или ошибки в оплате", "Использование процедуры для граждан не из списка 5 стран"]'::jsonb, '["Подавайте с запасом минимум 2-3 недели", "Проверяйте список исключённых должностей заранее", "Храните электронное подтверждение о внесении в реестр"]'::jsonb, '["praca.gov.pl", "psz.praca.gov.pl", "biznes.gov.pl"]'::jsonb, 'С 1 декабря 2025 действует новый закон, сбор повышен до 400 злотых; украинцы с временной защитой трудоустраиваются через отдельную процедуру повядомления.', 'работа', 'service', NULL, NULL),
  ('NIP (налоговый номер, физлицо)', '10-значный налоговый идентификационный номер. В большинстве случаев для физлица с PESEL, работающего по найму, отдельный NIP не нужен — используется PESEL. NIP нужен плательщикам НДС/взносов без PESEL или ведущим бизнес вне CEIDG.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До первой сделки/события, требующего налоговой идентификации, если PESEL не подходит.', 'Urząd Skarbowy по месту жительства; лично, по почте или электронно через Портал Податкове.', 'Будни, около 7:30/8:00-15:00/15:30.', 'Не всегда требуется; подать можно через podatki.gov.pl.', '["Форма NIP-7", "Действующий загранпаспорт или иной документ", "Документы, подтверждающие основание получения NIP", "Адрес фактического проживания"]'::jsonb, 'Бесплатно.', 'От нескольких дней до нескольких недель.', '["Проверьте, действительно ли нужен отдельный NIP", "Найдите форму NIP-7", "Заполните и приложите документы", "Подайте лично/по почте/электронно", "Получите присвоенный номер"]'::jsonb, '["Подача заявления при наличии PESEL без реальных оснований", "Неясно указанное основание для присвоения", "Путаница между NIP, REGON и PESEL"]'::jsonb, '["Уточните заранее у бухгалтера, нужен ли отдельный NIP", "При регистрации ИП через CEIDG NIP присваивается автоматически", "Проверить NIP можно бесплатно через CEIDG/GUS"]'::jsonb, '["podatki.gov.pl", "biznes.gov.pl"]'::jsonb, 'Для большинства работающих по найму с PESEL отдельный NIP не требуется.', 'налоги', 'service', NULL, NULL),
  ('ZUS — регистрация', 'Zakład Ubezpieczeń Społecznych — орган социального страхования Польши: пенсионное, инвалидное, больничное, от несчастных случаев и медицинское (NFZ). При найме регистрирует работодатель; при бизнесе — сам предприниматель.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Работодатель регистрирует в течение 7 дней с начала работы; самозанятые — одновременно с открытием бизнеса.', 'Через PUE ZUS (Platforma Usług Elektronicznych) или программу Płatnik; для ИП — автоматически при CEIDG-1.', 'Будни, около 8:00-15:00/18:00.', 'Формы подаются через PUE ZUS, запись не нужна; для консультации — по сайту/телефону.', '["Данные работника (ФИО, дата рождения, гражданство)", "PESEL и/или NIP", "Трудовой договор или договор-поручение", "Данные работодателя как плательщика взносов"]'::jsonb, 'Регистрация бесплатна; далее уплачиваются ежемесячные страховые взносы.', 'Несколько рабочих дней после подачи корректной формы.', '["Определите статус (найм или бизнес)", "Убедитесь, что работодатель зарегистрирован как плательщик", "Получите PESEL/NIP работника", "Заполните ZUS ZUA или ZZA через PUE ZUS", "Подайте в течение 7 дней с начала работы", "Ежемесячно подавайте отчёты и платите взносы"]'::jsonb, '["Просрочка 7-дневного срока регистрации", "Ошибки в идентификаторе работника", "Путаница между ZUA (полное страхование) и ZZA (только медицинское)"]'::jsonb, '["Заведите кабинет PUE ZUS заранее", "Без PESEL регистрация возможна по номеру паспорта, но лучше оформить PESEL как можно скорее", "Уточните льготы по взносам для начинающих предпринимателей"]'::jsonb, '["zus.pl", "PUE ZUS"]'::jsonb, 'Обязанность страхования определяется местом фактической работы, а не гражданством; продолжают действовать льготные периоды для начинающих ИП.', 'легализация', 'service', NULL, NULL),
  ('PIT — налоговая декларация', 'Годовая декларация о доходах физлица. Формы: PIT-37 (наёмный труд), PIT-36 (бизнес по общей шкале/доход напрямую от иностранного работодателя), PIT-36L (линейный налог), PIT-28 (ryczałt, включая аренду).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Ежегодно с 15 февраля по 30 апреля следующего года (PIT-28 — с 1 января).', 'Urząd Skarbowy по месту жительства или электронно через Twój e-PIT / e-Deklaracje на podatki.gov.pl.', 'Будни, около 7:30/8:00-15:00/15:30; Twój e-PIT доступен круглосуточно.', 'Не требуется, подача через Twój e-PIT.', '["Форма PIT-11 от работодателя или собственный учёт доходов", "PESEL и/или NIP", "Документы на налоговые льготы", "Сертификат налогового резидентства (при применении соглашения об избежании двойного налогообложения)", "Реквизиты счёта для возврата переплаты"]'::jsonb, 'Подача бесплатна; уплате подлежит только сам налог при доплате.', 'Возврат переплаты — 45 дней при электронной подаче, до 3 месяцев при бумажной.', '["Определите налоговый статус (резидент/нерезидент)", "Соберите данные о доходах", "Определите нужную форму", "Войдите в Twój e-PIT и проверьте предзаполненную декларацию", "Внесите льготы", "Подайте не позднее 30 апреля", "Уплатите доначисленный налог при необходимости"]'::jsonb, '["Пропуск срока подачи 30 апреля", "Неправильный выбор формы декларации", "Неучёт статуса налогового резидентства"]'::jsonb, '["Используйте Twój e-PIT для автозаполнения", "Сохраняйте PIT-11 от каждого работодателя", "Заранее подготовьте сертификат резидентства при льготах по соглашению"]'::jsonb, '["podatki.gov.pl", "Twój e-PIT"]'::jsonb, 'За 2025 год декларации подавались до 30 апреля 2026; за 2026 год — с 15 февраля по 30 апреля 2027; работодатели направляют PIT-11 до 31 января/28 февраля.', 'налоги', 'service', NULL, NULL),
  ('Регистрация ИП (JDG)', 'Jednoosobowa działalność gospodarcza — регистрация физлица как индивидуального предпринимателя через систему CEIDG. Предприниматель отвечает по обязательствам всем своим имуществом.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После получения легального основания пребывания и до начала коммерческой деятельности.', 'Онлайн через CEIDG (ceidg.gov.pl) или Biznes.gov.pl с Profil Zaufany; либо лично в Urząd Miasta/Gminy.', 'Будни, около 8:00-16:00/18:00.', 'Не требуется для онлайн-подачи; для личной — рекомендуется запись.', '["Загранпаспорт", "Документ о легальном основании пребывания", "PESEL (при наличии)", "Profil Zaufany или квалифицированная подпись", "Код(ы) PKD", "Адрес деятельности"]'::jsonb, 'Бесплатно.', 'Запись в CEIDG обычно в течение 1 рабочего дня.', '["Проверьте, позволяет ли статус пребывания регистрацию JDG", "Получите Profil Zaufany", "Определите коды PKD", "Заполните форму CEIDG-1 онлайн или лично", "Укажите форму налогообложения", "Данные автоматически передаются в ZUS, GUS, налоговую", "В течение 7 дней зарегистрируйтесь в ZUS"]'::jsonb, '["Регистрация без проверки, разрешён ли статус для JDG", "Неправильный выбор формы налогообложения на старте", "Игнорирование сроков регистрации в ZUS"]'::jsonb, '["Подача через CEIDG онлайн полностью бесплатна и быстрее визита", "Проконсультируйтесь с бухгалтером по форме налогообложения заранее", "С 2026 действует квартальный лимит для нерегистрируемой деятельности"]'::jsonb, '["ceidg.gov.pl", "biznes.gov.pl", "zus.pl"]'::jsonb, 'С 2026 действует квартальный (не месячный) лимит дохода для нерегистрируемой деятельности; ужесточены правила для ранее незарегистрированной деятельности.', 'бизнес', 'service', NULL, NULL),
  ('Регистрация ООО (Sp. z o.o.)', 'Общество с ограниченной ответственностью — учредители отвечают в пределах уставного капитала. Самая популярная форма юрлица среди иностранных предпринимателей.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'На этапе запуска бизнеса, до начала коммерческой деятельности.', 'Онлайн через систему S24 (Ministerstwo Sprawiedliwości) с Profil Zaufany, либо через нотариуса и регистрационный суд (Sąd Rejonowy, Wydział Gospodarczy KRS).', 'Суды: будни 8:00-15:30; нотариальные конторы: обычно 9:00-17:00.', 'Для S24 не требуется; для нотариуса — предварительная запись.', '["Загранпаспорта учредителей и директора(ов)", "Коды PKD", "Устав компании (типовой для S24 или индивидуальный у нотариуса)", "Подтверждение внесения уставного капитала (минимум 5000 злотых)", "Юридический адрес компании", "Profil Zaufany или квалифицированная подпись"]'::jsonb, 'Уставной капитал минимум 5000 злотых; сбор KRS около 500 злотых; публикация в MSiG около 100 злотых; налог PCC около 0,5% от капитала.', 'Через S24 — 1-5 рабочих дней; через нотариуса — 2-5 недель.', '["Определите состав учредителей и долей", "Выберите способ регистрации (S24 или нотариус)", "Получите Profil Zaufany", "Подготовьте и подпишите устав", "Внесите уставной капитал", "Подайте заявление в KRS", "Получите NIP и REGON", "Откройте расчётный счёт"]'::jsonb, '["Выбор типового устава S24 для сложной структуры владения", "Несвоевременное внесение уставного капитала", "Игнорирование отдельной регистрации плательщика НДС при необходимости"]'::jsonb, '["S24 значительно быстрее и дешевле нотариального варианта для простых случаев", "Уставной капитал можно частично использовать на операционные нужды после регистрации", "Директором может быть иностранец без ВНЖ в Польше"]'::jsonb, '["s24.gov.pl", "prs.ms.gov.pl", "biznes.gov.pl", "ekrs.ms.gov.pl"]'::jsonb, 'Продолжают ужесточаться требования к прозрачности бенефициарных владельцев (реестр CRBR).', 'бизнес', 'service', NULL, NULL),
  ('NIP для бизнеса', '10-значный налоговый номер для бизнеса, присваивается автоматически при регистрации JDG (CEIDG) или Sp. z o.o. (KRS) — отдельно подавать заявление не нужно.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Автоматически в процессе регистрации бизнеса.', 'Не требуется отдельная подача; для корректировки данных — форма NIP-8 в Urząd Skarbowy по месту регистрации бизнеса.', 'Urzędy Skarbowe: будни 8:00-15:00/18:00.', 'Не требуется.', '["Выписка из CEIDG или KRS с номером NIP", "Загранпаспорт", "Учредительные документы (для юрлиц)"]'::jsonb, 'Бесплатно.', 'Несколько рабочих дней после регистрации CEIDG/KRS.', '["Зарегистрируйте JDG или Sp. z o.o.", "Дождитесь автоматического присвоения NIP", "Проверьте номер в реестре CEIDG/KRS", "Для компаний — подайте форму NIP-8 с дополнительными данными"]'::jsonb, '["Ожидание бумажного письма вместо проверки в электронном реестре", "Пропуск срока подачи формы NIP-8 для компаний", "Путаница между NIP физлица и NIP для бизнеса"]'::jsonb, '["Проверить NIP можно бесплатно в CEIDG/KRS онлайн", "Для компаний не забудьте подать NIP-8", "Отдельно посещать налоговую для получения самого номера не требуется"]'::jsonb, '["ceidg.gov.pl", "ekrs.ms.gov.pl", "biznes.gov.pl", "podatki.gov.pl"]'::jsonb, 'Процедура полностью интегрирована с CEIDG и KRS; для компаний по-прежнему актуально своевременное представление формы NIP-8.', 'бизнес', 'service', NULL, NULL),
  ('REGON', 'Уникальный статистический номер (9 знаков для предпринимателей, 14 для филиалов), присваиваемый GUS. Требуется практически во всех официальных документах компании.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Автоматически при регистрации JDG (CEIDG) или Sp. z o.o. (KRS).', 'Не требуется отдельная подача; для филиалов иностранных компаний — региональное управление GUS.', 'Будни 8:00-15:30.', 'Не требуется.', '["Выписка из CEIDG или KRS с номером REGON", "Загранпаспорт", "Учредительные документы (для филиалов)"]'::jsonb, 'Бесплатно.', '1-3 рабочих дня после регистрации бизнеса.', '["Зарегистрируйте JDG или Sp. z o.o.", "Дождитесь автоматического присвоения REGON вместе с NIP", "Проверьте номер в реестре CEIDG или на stat.gov.pl", "Для филиалов иностранных компаний — подайте отдельное заявление в GUS"]'::jsonb, '["Ожидание отдельного письма вместо использования уже присвоенного номера", "Путаница между REGON, NIP и номером KRS", "Использование устаревшего REGON после смены адреса/деятельности"]'::jsonb, '["Проверить REGON можно мгновенно на stat.gov.pl", "Отдельно получать REGON не нужно для большинства предпринимателей", "Держите REGON, NIP и KRS/CEIDG единым списком"]'::jsonb, '["stat.gov.pl", "ceidg.gov.pl", "ekrs.ms.gov.pl"]'::jsonb, 'Для большинства предпринимателей процесс полностью автоматизирован; исключение — филиалы иностранных компаний.', 'бизнес', 'service', NULL, NULL),
  ('VAT регистрация', 'Регистрация плательщика VAT (форма VAT-R) даёт право и обязанность начислять и вычитать налог на добавленную стоимость. VAT-UE — отдельная регистрация для работы с контрагентами из ЕС.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До превышения лимита 240 000 злотых в год (2026) либо сразу для видов деятельности без права на освобождение; VAT-UE — до первой сделки с ЕС.', 'Онлайн через Biznes.gov.pl/ePUAP или лично/по почте в Urząd Skarbowy по месту регистрации бизнеса.', 'Будни 8:00-15:00/18:00.', 'Не требуется для онлайн-подачи.', '["Форма VAT-R", "Выписка из CEIDG/KRS с NIP и REGON", "Загранпаспорт"]'::jsonb, 'Подача бесплатна; возможен небольшой гербовый сбор за подтверждающий документ.', 'До нескольких рабочих дней; возможна дополнительная проверка новых компаний.', '["Определите, обязаны ли вы регистрироваться как плательщик VAT", "Учтите необходимость VAT-UE при работе с ЕС", "Заполните форму VAT-R", "Подайте онлайн или лично", "Проверьте статус в реестре Wykaz podatników VAT", "Начните вести учёт и подавать JPK_VAT"]'::jsonb, '["Пропуск обязательной регистрации при превышении лимита оборота", "Работа с контрагентами ЕС без VAT-UE", "Путаница между внутренним лимитом и обязательствами по VAT-UE"]'::jsonb, '["При больших расходах с VAT может быть выгодна добровольная регистрация раньше", "Проверяйте статус свой и контрагентов в Biała lista", "Уточните заранее, нужна ли VAT-UE"]'::jsonb, '["Biznes.gov.pl", "podatki.gov.pl (Biała lista)", "epuap.gov.pl"]'::jsonb, 'С 2026 лимит освобождения увеличен с 200 000 до 240 000 злотых в год; действует переходное положение при превышении в 2025 году.', 'бизнес', 'service', NULL, NULL),
  ('Счёт в банке для бизнеса', 'Расчётный счёт (rachunek firmowy) на имя ИП или компании для расчётов, связанных с бизнесом. Обязателен для операций свыше 15 000 злотых.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после регистрации бизнеса и получения NIP/REGON.', 'Отделение выбранного банка или онлайн; уточните возможность удалённого открытия по запросу.', 'Будни 9:00-18:00, иногда суббота.', 'Во многих банках доступна предварительная запись онлайн.', '["Загранпаспорт", "Выписка из CEIDG/KRS с NIP и REGON", "PESEL (при наличии)", "Учредительные документы (для Sp. z o.o.)"]'::jsonb, 'Отдельно от абонентского обслуживания (0-50+ злотых/мес.), само открытие обычно бесплатно.', 'От нескольких часов до нескольких дней.', '["Зарегистрируйте бизнес и получите NIP/REGON", "Выберите банк, сравнив тарифы", "Запишитесь на приём", "Подготовьте документы", "Пройдите идентификацию личности", "Подпишите договор", "Получите реквизиты счёта"]'::jsonb, '["Обращение только в один банк без альтернатив при отказе", "Использование личного счёта вместо расчётного для операций бизнеса", "Недооценка времени на compliance-проверку"]'::jsonb, '["Сравнивайте условия нескольких банков заранее", "Уточните требования к удалённому открытию для директоров-нерезидентов", "Держите наготове полный пакет документов"]'::jsonb, '["сайты банков (PKO BP, mBank, ING, Santander, Millennium, Credit Agricole, Alior)", "biznes.gov.pl"]'::jsonb, 'Банки продолжают ужесточать проверку KYC/compliance для компаний с иностранными учредителями.', 'бизнес', 'service', NULL, NULL),
  ('Печать компании', 'Pieczątka firmowa — штамп с реквизитами фирмы. С 2019 года юридически не обязательна ни для ИП, ни для ООО, но на практике часто ожидается банками и контрагентами.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После регистрации бизнеса, когда присвоен NIP (и для ООО — KRS).', 'Частные мастерские (grawernia, punkty pieczątkarskie) или интернет-магазины печатей.', 'Зависит от мастерской.', 'Не требуется, заказ оформляется онлайн или лично.', '["Выписка из CEIDG или KRS", "NIP компании", "Для ООО — номер KRS, суд регистрации, размер капитала"]'::jsonb, 'Зависит от изготовителя и материала.', 'От нескольких часов до 1-3 рабочих дней.', '["Зарегистрируйте бизнес и получите NIP (и KRS для ООО)", "Определите необходимые данные на печати", "Выберите изготовителя", "Подготовьте макет", "Оплатите и получите готовую печать"]'::jsonb, '["Ошибки в NIP/KRS на печати", "Трата времени на печать до реальной необходимости", "Использование устаревших данных после смены адреса"]'::jsonb, '["Печать не обязательна — можно начать без неё", "Закажите сразу электронную версию оттиска", "Проверяйте макет перед печатью"]'::jsonb, '["biznes.gov.pl"]'::jsonb, 'Обязанность иметь печать отменена с 2019 года и остаётся отменённой; ни налоговая, ни ZUS её не требуют.', 'бизнес', 'service', NULL, NULL),
  ('Зачисление в университет', 'Официальное подтверждение зачисления от польского университета — необходимо для студенческой визы D и студенческой карты побыту.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До отъезда из своей страны, подавать до конца июля для учёбы с октября.', 'Напрямую через сайт выбранного университета (раздел Rekrutacja).', 'Онлайн-подача круглосуточно; приёмная комиссия обычно пн-пт 9:00-15:00.', 'Через сайт университета.', '["Загранпаспорт", "Аттестат/диплом с переводом на польский у присяжного переводчика", "Апостиль на аттестат/диплом", "Сертификат B2 польского или английского", "Фото 3.5x4.5 (4 шт.)", "Заявление на поступление", "Квитанция об оплате взноса"]'::jsonb, 'Вступительный взнос 20-30 €; перевод документов 100-300 злотых.', 'Официально 30 дней, реально 2-4 недели.', '["Выберите университет и специальность", "Зарегистрируйтесь в системе Rekrutacja", "Заполните заявление онлайн", "Подготовьте документы (аттестат, перевод, апостиль)", "Загрузите документы", "Оплатите взнос 20-30 €", "Дождитесь подтверждения", "Используйте письмо о зачислении для визы D или карты побыту"]'::jsonb, '["Отсутствие апостиля на аттестат", "Слишком поздняя подача — места на популярные специальности заканчиваются", "Обычный перевод вместо присяжного"]'::jsonb, '["Подавайте в несколько университетов одновременно", "Частные вузы принимают проще", "Владельцы Карты поляка учатся бесплатно"]'::jsonb, '["polon.nauka.gov.pl"]'::jsonb, 'С 2025 иностранные абитуриенты обязаны подтвердить уровень языка не ниже B2; уточняйте условия для украинцев со статусом временной защиты.', 'образование', 'service', NULL, NULL),
  ('Студенческая карта побыту (karta pobytu na naukę)', 'Пластиковая ID-карта, подтверждающая право иностранного студента легально находиться в Польше на весь период учёбы, заменяет необходимость регулярно продлевать визу.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После зачисления и получения учебной визы, за 30-45 дней до истечения легального пребывания.', 'Wydział Spraw Cudzoziemców соответствующего Urząd Wojewódzki по месту проживания.', 'Уточняйте на сайте управления.', 'Через MOS с Profil Zaufany.', '["Загранпаспорт", "Заявление на zezwolenie na pobyt czasowy", "Подтверждение зачисления в вуз", "Подтверждение оплаты обучения (если применимо)", "Подтверждение жилья", "Подтверждение финансовых средств", "Медстраховка", "Фотографии"]'::jsonb, 'Пошлина 340 злотых; отдельно — плата за изготовление карты.', 'Первое разрешение обычно на 15 месяцев, далее на весь срок учёбы (до 3 лет).', '["Получите подтверждение зачисления", "Оформите учебную визу D при необходимости", "Зарегистрируйте адрес (meldunek)", "Заведите Profil Zaufany и аккаунт MOS", "Подайте заявление на pobyt czasowy", "Оплатите пошлину", "Явитесь на биометрию", "Получите готовую карту"]'::jsonb, '["Подача слишком поздно", "Неполный пакет документов (страховка, финансы)", "Отсутствие актуальной регистрации адреса"]'::jsonb, '["Подавайте заранее, не дожидаясь последних дней легальности", "Сохраняйте копию заявления и штамп о приёме", "Проверьте требования к фото и переводам заранее"]'::jsonb, '["mos.cudzoziemcy.gov.pl", "gov.pl"]'::jsonb, 'С 27 апреля 2026 действует обновлённая система MOS; с 4 мая 2026 для граждан со статусом UKR доступна карта CUKR, что прекращает льготы UKR — консультируйтесь с деканатом заранее.', 'легализация', 'service', NULL, NULL),
  ('Нострификация диплома', 'Официальная процедура признания иностранного диплома эквивалентным польскому. Нужна для регулируемых профессий (врач, юрист, архитектор, учитель) или продолжения обучения.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед трудоустройством по регулируемой профессии или продолжением обучения.', 'Университеты с научной категорией A+/A/B+ по нужной дисциплине (список на сайте NAWA).', 'Разные по вузам, часто ограниченные часы приёма (напр. вт 7:30-10:30, ср 10:00-13:00).', 'Предварительная запись по email/телефону в выбранном вузе.', '["Заявление о нострификации", "Оригинал диплома и трансскрипт", "Документ, на основании которого был принят на обучение", "Присяжный перевод на польский", "Документ о смене имени (если применимо)", "Подтверждение оплаты"]'::jsonb, 'Около 4685-4825 злотых в большинстве вузов; для отдельных программ (напр. для украинцев) — около 3205 злотых или бесплатно.', 'Не более 90 дней с момента получения полного пакета документов (без учёта переводов и экзаменов).', '["Определите, требуется ли нострификация", "Найдите уполномоченный вуз", "Свяжитесь с офисом нострификации", "Подготовьте документы и переводы", "Подайте заявление и оплатите сбор", "При необходимости пройдите экзамены", "Дождитесь решения (uchwałę)"]'::jsonb, '["Подача без официального присяжного перевода", "Обращение не в тот вуз по научной категории", "Отсутствие документа об основании приёма на обучение"]'::jsonb, '["Уточните у работодателя, действительно ли нострификация обязательна для профессии", "Закажите присяжный перевод пакетом заранее", "Проверьте автоматическое признание по международному соглашению"]'::jsonb, '["nawa.gov.pl"]'::jsonb, 'С 1 мая 2026 размер платы проиндексирован и в ряде вузов составляет 4825 злотых.', 'образование', 'service', NULL, NULL),
  ('Апостиль на документы', 'Международное упрощённое удостоверение подлинности официального документа по Гаагской конвенции 1961 года. Ставится в стране выдачи документа.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Заранее, до отъезда в Польшу для документов из страны происхождения.', 'Для документов из Польши: MSZ (Wydział Legalizacji, ul. Krucza 38/42, Варшава) — гражданские документы; NAWA (ul. Polna 40, Варшава) — дипломы; предварительно Sąd Okręgowy — для нотариальных документов. Для документов из своей страны — уполномоченный орган этой страны.', 'Приём в MSZ — будни 9:00-14:00.', 'Через e-konsulat.gov.pl.', '["Оригинал документа (не копия)", "Заполненное заявление на апостиль", "Подтверждение оплаты", "Для нотариальных документов — предварительное заверение суда"]'::jsonb, '60 злотых за документ в Польше; плюс около 26 злотых за заверение суда для нотариальных документов.', 'От нескольких часов до 5 рабочих дней, при большой загрузке — до 2-3 недель.', '["Определите страну выдачи документа", "Определите нужное учреждение (MSZ, NAWA или суд)", "Подготовьте оригинал", "Заполните заявление", "Оплатите сбор", "Подайте документы", "Получите документ с апостилем"]'::jsonb, '["Попытка апостилировать копию вместо оригинала", "Обращение не в тот орган", "Отсутствие апостиля на документах из своей страны ещё до переезда"]'::jsonb, '["Проставьте апостиль на ключевые документы заранее, в своей стране", "Заказывайте апостиль сразу на несколько документов", "Уточните у принимающей стороны, точно ли требуется апостиль"]'::jsonb, '["gov.pl (MSZ Apostille)", "nawa.gov.pl", "Гаагская конференция по МЧП"]'::jsonb, 'Апостиль нельзя поставить на ксерокопию или распечатку с ePUAP; NAWA апостилирует только польские дипломы.', 'документы', 'service', NULL, NULL),
  ('Перевод документов (присяжный)', 'Официальный перевод, выполненный присяжным переводчиком (tłumacz przysięgły) из реестра Минюста Польши, с юридической силой для госорганов, судов, вузов и работодателей.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед подачей иностранных документов в польские учреждения.', 'Напрямую у присяжного переводчика (реестр Минюста) или в бюро переводов.', 'Зависит от переводчика.', 'Часто не требуется, заказ по email/сайту.', '["Оригинал документа (или заверенная копия)", "Паспортные данные для точного написания имени"]'::jsonb, 'Официальный минимум для госзаказов — от 44 злотых за страницу (1125 знаков); частные заказы обычно дороже, от 45-80 злотых/страницу.', 'От 1 до нескольких рабочих дней; срочно — за сутки с доплатой.', '["Определите нужные документы и язык перевода", "Найдите присяжного переводчика в реестре Минюста", "Отправьте скан для оценки", "Согласуйте сроки и цену", "Предоставьте оригинал", "Оплатите и получите перевод"]'::jsonb, '["Заказ обычного перевода там, где нужен присяжный", "Несоответствие написания имени в разных документах", "Перевод без обязательного апостиля на оригинал"]'::jsonb, '["Уточните у учреждения, какой именно перевод нужен", "Заказывайте несколько документов у одного переводчика", "Сохраняйте электронную копию перевода"]'::jsonb, '["Минюст Польши (реестр tłumacze przysięgli)"]'::jsonb, 'Официальные ставки основаны на распоряжении Минюста от 16.10.2023, актуальны как ориентир в 2026 году.', 'документы', 'service', NULL, NULL),
  ('Студенческая карта ISIC', 'Международная студенческая карта, признаваемая в 130+ странах — даёт скидки на транспорт, жильё, музеи. Не заменяет польскую студенческую легитимацию для местных льгот (напр. на ж/д транспорте).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После получения студенческого статуса, особенно при планируемых поездках за границу.', 'Онлайн через isic.org или партнёрские пункты выдачи (университетские магазины, Almatur).', 'Онлайн — круглосуточно.', 'Через сайт ISIC, отдельная запись не нужна.', '["Фотография", "Документ, подтверждающий статус учащегося", "Подтверждение возраста (обычно до 30 лет)"]'::jsonb, '29 злотых без страховки; 75 злотых со страховкой по Польше; 105 злотых со страховкой на весь мир.', 'От нескольких дней до 2-3 недель на изготовление и доставку.', '["Подготовьте фото и подтверждение статуса", "Заполните онлайн-форму на isic.org", "Выберите тип карты", "Оплатите заказ", "Дождитесь изготовления/активации", "Проверьте данные на карте"]'::jsonb, '["Оформление без реальной необходимости в зарубежных поездках", "Путаница между ISIC и польской студенческой легитимацией", "Выбор пакета страховки без учёта территории поездок"]'::jsonb, '["При частых поездках выбирайте пакет со страховкой", "Держите оба документа — польскую легитимацию и ISIC", "Проверяйте перед поездкой, принимают ли конкретные партнёры скидку"]'::jsonb, '["isic.org"]'::jsonb, 'ISIC действует максимум 16 месяцев, требует продления при долгом обучении.', 'образование', 'service', NULL, NULL),
  ('Карта побыту для члена семьи гражданина ЕС/Польши', 'Karta pobytu członka rodziny obywatela UE/RP — подтверждает право пребывания члена семьи гражданина ЕС или Польши, если сам он не гражданин ЕС/ЕЭЗ/Швейцарии. Отдельный документ от карты побыту для семьи иностранца-резидента (док №15).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее чем через 3 месяца после въезда и начала совместного проживания.', 'Wydział Spraw Cudzoziemców соответствующего Urząd Wojewódzki по месту проживания.', 'Будни 8:00/9:00-15:00/16:00.', 'Через MOS (mos.cudzoziemcy.gov.pl) и систему e-usług воеводства; личная явка обязательна.', '["Бланк заявления", "Загранпаспорт", "Свидетельство о браке/рождении с присяжным переводом", "4 биометрических фото", "Документ о праве пребывания гражданина ЕС/Польши", "Подтверждение иждивения (для детей старше 21 года/родителей)"]'::jsonb, 'Выдача карты — бесплатно; доверенность (если через представителя) — 17 злотых.', 'Не позднее 6 месяцев со дня подачи.', '["Соберите документы, включая переведённое свидетельство о браке/рождении", "Запишитесь через MOS или e-usługi", "Явитесь лично, подайте заявление, сдайте биометрию", "Получите подтверждение приёма", "Дождитесь решения", "Заберите готовую карту лично"]'::jsonb, '["Подача документов о браке/родстве без апостиля и присяжного перевода", "Пропуск 3-месячного срока с момента въезда", "Попытка подать через представителя без личной явки при первичной подаче"]'::jsonb, '["Подавайте за 3-4 недели до истечения 3-месячного срока", "Сделайте присяжный перевод заранее", "Подтверждение подачи легализует пребывание на время рассмотрения"]'::jsonb, '["mos.cudzoziemcy.gov.pl", "gov.pl/web/mswia", "gov.pl/web/profilzaufany"]'::jsonb, 'С 17 апреля 2026 отключена прежняя версия MOS, нужен новый профиль.', 'легализация', 'service', NULL, NULL),
  ('Документы для детей в школу', 'Пакет документов для зачисления ребёнка-иностранца в школу. Обязательное школьное обучение (obowiązek szkolny) для детей 7-18 лет действует независимо от гражданства и статуса родителей, бесплатно.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед началом учебного года (март-апрель на 1 класс, до конца августа на перевод) либо в любой момент при переезде не летом.', 'Секретариат выбранной школы по месту жительства (rejonizacja) или вне района при наличии мест; информация — через Kuratorium Oświaty региона.', 'Секретариаты школ обычно 8:00-15:00/16:00.', 'В части городов — элektronный набор (nabór elektroniczny) для 1 класса и лицеев.', '["Заявление о приёме", "Свидетельство о рождении ребёнка с переводом", "Документ родителя/опекуна", "Подтверждение адреса проживания", "Табель/аттестат из прежней школы (при наличии)", "Апостиль на документ об образовании (для стран не ЕС)", "Присяжный перевод документов об образовании"]'::jsonb, 'Обучение бесплатно; платны только присяжный перевод и апостиль.', 'Решение обычно в течение нескольких дней после подачи полного пакета.', '["Определите школу по месту жительства или выберите вне района", "Закажите присяжный перевод свидетельства и табеля", "Оформите апостиль при необходимости", "Обратитесь в секретариат и подайте документы", "При отсутствии документов пройдите квалификационную беседу", "Дождитесь решения директора"]'::jsonb, '["Обращение без перевода свидетельства о рождении и табеля", "Ожидание готовности PESEL перед подачей — PESEL не обязателен", "Игнорирование права на бесплатные занятия польским языком"]'::jsonb, '["При отсутствии табеля возможна квалификационная беседа на родном языке", "Уточните список документов конкретной школы заранее по email/телефону"]'::jsonb, '["powroty.gov.pl", "gov.pl (образование для украинских детей)"]'::jsonb, 'Правила регулируются постановлением от 23.08.2017, актуальным в 2026 году; для украинских детей действуют дополнительные упрощённые правила приёма.', 'образование', 'service', NULL, NULL),
  ('Документы для детей в садик', 'Пакет документов для зачисления ребёнка-иностранца в детский сад (3-6 лет; для 6-летних — обязательная подготовительная группа, гмина обязана обеспечить место).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Основной набор — март-май на учебный год с сентября; дополнительный — май-июнь; в течение года при переезде не летом.', 'Выбранный детский сад лично либо через электронную систему набора города/гмины; общий реестр — rspo.gov.pl.', 'Секретариаты садиков — будни 8:00-16:00.', 'В крупных городах — элektронная реĸрутация с уĸазанием приоритетных садов.', '["Заявление о приёме", "Свидетельство о рождении ребёнка (по требованию — с переводом)", "Документ родителя/опекуна", "Документы, подтверждающие критерии приёма", "PESEL ребёнка (включая PESEL UKR для украинских детей)", "Медсправка/сведения о прививках (по требованию)", "Присяжный перевод свидетельства о рождении (для групп А и Б)"]'::jsonb, 'Базовые 5 часов в день бесплатно; доп. часы и питание по тарифу гмины; частные сады — 800-4500 злотых/мес.', 'Списки публикуются через несколько недель после закрытия набора; вне набора — несколько дней.', '["Проверьте реестр садиков в вашем районе", "Выберите несколько садиков по приоритету", "Закажите перевод свидетельства при необходимости", "Заполните заявление онлайн или в садике", "Подайте документы лично в садик первого приоритета", "Подтвердите намерение после публикации списка квалифицированных", "Подпишите договор с садиком"]'::jsonb, '["Пропуск этапа подтверждения воли после публикации списка", "Подача только в один садик без приоритетов", "Отсутствие присяжного перевода, если садик его требует"]'::jsonb, '["Указывайте максимум разрешённых садиков по приоритету", "При дороге свыше 3 км гмина обязана обеспечить транспорт", "Вне сезона набора обращайтесь напрямую в садики о свободных местах"]'::jsonb, '["rspo.gov.pl", "ukrainianinpoland.pl"]'::jsonb, 'Сроки и правила набора устанавливает каждая гмина индивидуально; для украинских детей продолжает действовать указание PESEL UKR в заявках.', 'образование', 'service', NULL, NULL),
  ('Свидетельство о браке (перевод)', 'Присяжный перевод свидетельства о браке на польский язык, принимаемый ЗАГСами, воеводскими управлениями, банками и работодателями наравне с оригиналом.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Заранее, до подачи заявления, где требуется этот документ (карта побыту, PESEL, воссоединение семьи и т.д.).', 'Напрямую у присяжного переводчика или бюро переводов; официальный реестр переводчиков — arch-bip.ms.gov.pl.', 'Зависит от переводчика/бюро, обычно 9:00-17:00.', 'Часто не требуется, заказ через email/сайт.', '["Оригинал свидетельства о браке (или официальная копия)", "Апостиль/консульская легализация (для стран, не входящих в ЕС и без упрощённого признания)", "Документ, удостоверяющий личность заказчика"]'::jsonb, 'Ориентировочно 50-70 злотых нетто за расчётную страницу (1125 знаков); срочный перевод дороже на 50-100%.', '1-3 рабочих дня; срочно — 1 день с доплатой.', '["Проверьте, нужен ли апостиль для вашей страны и цели", "При необходимости оформите апостиль в стране выдачи", "Выберите присяжного переводчика", "Отправьте скан на оценку", "Оплатите и предоставьте оригинал", "Получите готовый перевод", "Подайте вместе с оригиналом в нужное учреждение"]'::jsonb, '["Заказ перевода до получения апостиля (придётся переводить заново)", "Обращение к обычному, не присяжному переводчику", "Использование устаревшей выписки вместо актуальной"]'::jsonb, '["Для стран Венской конвенции 1976 запросите многоязычную форму — перевод не нужен", "Заказывайте перевод свидетельства о браке и рождении у одного переводчика", "Уточните, нужен ли перевод оригинала или заверенной копии"]'::jsonb, '["arch-bip.ms.gov.pl (Lista tłumaczy przysięgłych)", "gov.pl (Urząd Stanu Cywilnego)"]'::jsonb, 'Требования к апостилю/легализации по-прежнему определяются страной происхождения и типом процедуры.', 'документы', 'service', NULL, NULL),
  ('Свидетельство о рождении (перевод)', 'Присяжный перевод свидетельства о рождении на польский язык, принимаемый ЗАГСами, воеводством, садиками/школами наравне с оригиналом.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Заранее, до подачи заявления на PESEL, карту побыту, зачисление в садик/школу и т.д.', 'Напрямую у присяжного переводчика или бюро переводов из реестра Минюста.', 'Зависит от переводчика/бюро, обычно 9:00-17:00.', 'Часто не требуется, заказ через email/сайт.', '["Оригинал свидетельства о рождении (краткая или полная выписка)", "Апостиль/консульская легализация (при необходимости)", "Документ, удостоверяющий личность заказчика"]'::jsonb, 'Краткая выписка около 55-80 злотых, полная — 100-150 злотых; с украинского около 130 злотых.', '1-3 рабочих дня; срочно — 1 день с доплатой.', '["Проверьте, нужен ли апостиль", "При необходимости оформите апостиль в стране выдачи", "Выберите присяжного переводчика", "Отправьте скан на оценку", "Оплатите и предоставьте оригинал", "Получите готовый перевод", "Подайте вместе с оригиналом в учреждение"]'::jsonb, '["Заказ перевода до получения апостиля", "Обращение к не присяжному переводчику", "Использование краткой выписки там, где нужна полная (odpis zupełny)"]'::jsonb, '["Для стран Венской конвенции 1976 запросите многоязычную форму", "Заказывайте перевод свидетельства о рождении вместе со свидетельством о браке", "Уточните заранее, нужна краткая или полная выписка"]'::jsonb, '["arch-bip.ms.gov.pl (Lista tłumaczy przysięgłych)", "gov.pl (Urząd Stanu Cywilnego)"]'::jsonb, 'Требования к виду выписки (краткая/полная) отличаются в зависимости от процедуры (PESEL, ЗАГС, садик/школа).', 'документы', 'service', NULL, NULL),
  ('Банковский счёт физлица', 'Личный счёт в польском банке для зарплаты и повседневных расходов. Открытие максимально простое, у ряда банков (mBank, Revolut) — полностью онлайн в течение одного дня.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'После приезда в Польшу; часть банков (mBank, Revolut) позволяют открыть счёт онлайн ещё до приезда.', 'Отделение банка лично или онлайн (mbank.pl, ing.pl, revolut.com, pkobp.pl, pekao.com.pl, santander.pl).', 'Отделения обычно пн-пт 9:00-18:00, сб 9:00-13:00; онлайн — круглосуточно.', 'Через сайт/приложение банка.', '["Загранпаспорт (оригинал)", "PESEL (желательно, большинство банков требуют)", "Подтверждение легального пребывания", "Подтверждение адреса проживания", "Справка с места работы/учёбы (иногда)"]'::jsonb, 'Открытие обычно бесплатно; обслуживание 0-10 злотых/мес.; Revolut бесплатно при базовом тарифе.', 'Revolut — 10-15 минут онлайн; mBank онлайн — 1 день; обычный банк лично — в день обращения; карта по почте — 5-7 дней.', '["Выберите банк (Revolut или mBank для старта)", "Зайдите на сайт/в приложение", "Заполните анкету", "Пройдите верификацию (фото паспорта + селфи)", "Подпишите договор", "Получите реквизиты счёта", "Закажите карту"]'::jsonb, '["Обращение в PKO BP/Pekao без PESEL — часто отказывают", "Отсутствие договора аренды для подтверждения адреса", "Гражданам России обращение в обычные банки вместо Revolut/mBank"]'::jsonb, '["Revolut открывается за 10 минут без визита и без PESEL", "mBank самый лояльный из польских банков для иностранцев", "Граждане ЕС открывают счёт как граждане Польши"]'::jsonb, '["mbank.pl", "ing.pl", "revolut.com", "pkobp.pl", "pekao.com.pl"]'::jsonb, 'Иностранцы без карты побыту или гражданства ЕС проходят более строгие проверки AML/KYC; минимальная зарплата в Польше с 1 января 2026 — 4806 злотых брутто.', 'банки', 'service', NULL, 'mbank.pl'),
  ('Банковский счёт для бизнеса', 'Расчётный счёт на юрлицо (Sp. z o.o.) или ИП (JDG), через который проходят все операции компании. Платежи между предпринимателями свыше 15 000 злотых обязаны идти через такой счёт.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после регистрации компании; для Sp. z o.o. часто нужен уже на этапе внесения уставного капитала.', 'Отделение банка или дистанционная видеоверификация; наиболее лояльные — PKO Bank Polski, Santander, mBank, BNP Paribas, ING Bank Śląski.', 'Обычно 9:00-17:00/18:00 в будни.', 'Через сайт/приложение банка; часть банков предлагает полностью удалённое открытие.', '["Загранпаспорта совладельцев/бенефициаров", "PESEL (при наличии)", "Документ о легальном пребывании (для не ЕС)", "Выписка из KRS/CEIDG", "NIP и REGON", "Устав/учредительный договор", "Данные о бенефициарах (CRBR)", "Формы KYC/AML"]'::jsonb, 'Открытие обычно бесплатно; обслуживание 0-50 злотых/мес.', 'От 1 дня до 2 недель; сложные структуры — дольше.', '["Зарегистрируйте компанию и получите NIP/REGON", "Выберите банк", "Запишитесь на визит или уточните удалённое открытие", "Подготовьте документы компании", "Заполните формы KYC/AML", "Пройдите верификацию", "Подпишите договор, получите IBAN"]'::jsonb, '["Подача без подтверждения реальной связи бизнеса с Польшей", "Несовпадение данных в KRS, CRBR и CEIDG", "Использование личного счёта для расчётов компании"]'::jsonb, '["Подготовьте краткое описание бизнеса и источников дохода заранее", "Проверьте актуальность данных в KRS/CRBR/CEIDG перед визитом", "Соберите договоры с контрагентами для снижения вопросов по AML"]'::jsonb, '["сайты банков PKO Bank Polski, Santander, mBank, ING", "ekrs.ms.gov.pl"]'::jsonb, 'Банки продолжают ужесточать AML-проверку для компаний с иностранными бенефициарами; платежи свыше 15 000 злотых обязаны идти через бизнес-счёт.', 'банки', 'service', NULL, NULL),
  ('Карта Revolut', 'Финтех-сервис (необанк) с мультивалютным счётом, дебетовой картой и выгодной конвертацией валют через мобильное приложение — популярная альтернатива классическому банку.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В любой момент, лучше сразу после получения PESEL, чтобы избежать ограничений на пополнение.', 'Полностью через мобильное приложение Revolut (iOS/Android), без визита в отделение.', 'Приложение и поддержка — 24/7.', 'Не требуется, регистрация в приложении.', '["Загранпаспорт (для фото-верификации)", "Номер телефона", "PESEL (если Польша указана страной проживания)", "Селфи для биометрии"]'::jsonb, 'Базовый тариф бесплатный; платные тарифы (Plus, Premium, Metal) от нескольких до нескольких десятков злотых/мес.', 'Виртуальная карта — сразу; физическая — до 2 недель.', '["Скачайте приложение Revolut", "Зарегистрируйтесь по номеру телефона", "Загрузите фото паспорта и пройдите верификацию", "Укажите страну проживания", "Активируйте виртуальную карту", "При необходимости введите PESEL для снятия ограничений"]'::jsonb, '["Указание Польши страной проживания без последующего PESEL — блокирует пополнение", "Использование Revolut как единственного счёта для зарплаты/бизнеса", "Смена страны проживания без реального переезда"]'::jsonb, '["Без PESEL можно временно указать другую страну проживания для верификации", "Проверяйте курс конвертации в приложении перед крупными переводами", "Для платежей свыше 15 000 злотых между предпринимателями нужен полноценный бизнес-счёт"]'::jsonb, '["revolut.com"]'::jsonb, 'С конца 2025 Revolut активно проверяет налоговое резидентство в рамках CRS; без PESEL при указанной Польше пополнение блокируется.', 'банки', 'service', NULL, 'revolut.com'),
  ('Перевод денег из своей страны', 'Отправка средств со счёта/карты в стране происхождения на счёт в Польше. Способ и надёжность сильно зависят от страны отправителя и санкционных ограничений.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед переездом или сразу после открытия счёта в Польше.', 'Через банк, мобильное приложение банка или международные сервисы (Wise, Revolut, Western Union, MoneyGram); нужен IBAN получателя (PL + 26 цифр).', 'Онлайн-переводы — круглосуточно; через отделение — часы работы банка.', 'Не требуется.', '["Паспорт для верификации", "IBAN и данные получателя", "Документ-основание перевода для крупных сумм"]'::jsonb, 'SEPA внутри ЕС — бесплатно/несколько евро; SWIFT — 15-50 €; Wise и аналоги — обычно дешевле SWIFT.', 'SEPA — 1 рабочий день; SWIFT — 1-5 дней; транзитные маршруты (Россия/Беларусь) — от нескольких дней до недели.', '["Определите сумму и способ перевода", "Уточните актуальный рабочий маршрут для вашей страны", "Подготовьте данные получателя (IBAN, ФИО)", "Для крупных сумм подготовьте документ-основание", "Оформите перевод", "Сохраните подтверждение", "Проверьте зачисление"]'::jsonb, '["Использование заблокированного/ненадёжного маршрута без проверки", "Отправка крупной суммы без документа-основания", "Ошибка в IBAN или данных получателя"]'::jsonb, '["Для небольших регулярных переводов Wise/Revolut обычно выгоднее SWIFT", "Уточняйте лимит, после которого банк запрашивает подтверждение источника средств", "Не разбивайте крупные суммы на части без консультации с банком"]'::jsonb, '["wise.com", "revolut.com"]'::jsonb, 'Переводы из России и Беларуси остаются одним из самых сложных направлений из-за отключения от SWIFT; для сумм свыше 5000 € польские банки могут требовать подтверждение источника средств.', 'банки', 'service', NULL, NULL),
  ('Регистрация в NFZ', 'Narodowy Fundusz Zdrowia — система обязательного медстрахования Польши. Регистрация не оформляется отдельным документом — статус формируется автоматически на основании трудоустройства/самозанятости/добровольного договора и проверяется через PESEL в eWUŚ.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после трудоустройства (работодатель регистрирует в течение 7 дней) или после получения PESEL для добровольного страхования.', 'Автоматически через ZUS при трудоустройстве/ИП; для добровольного страхования — заявление в отделение NFZ/ZUS.', 'Обычно 8:00-16:00 в будни.', 'Для добровольного страхования — через PUE ZUS или по телефону.', '["Паспорт", "PESEL", "Трудовой договор (umowa o pracę/zlecenie)", "Заявление ZUS ZUA (для добровольного)", "Документ о легальности пребывания", "Документы членов семьи для добавления к страховке"]'::jsonb, 'Через трудоустройство — бесплатно для сотрудника (платит работодатель); добровольное — ежемесячный взнос по тарифу NFZ.', 'Статус в eWUŚ обычно обновляется в течение нескольких рабочих дней.', '["Убедитесь в наличии PESEL", "При трудоустройстве — сообщите данные работодателю", "Самозанятые регистрируются в ZUS сами", "Без трудового основания — подайте ZUS ZUA", "Проверьте статус в eWUŚ", "Добавьте членов семьи при необходимости", "Выберите семейного врача POZ"]'::jsonb, '["Ошибочная уверенность, что статус UKR по-прежнему автоматически даёт бесплатный NFZ (отменено с 5 марта 2026)", "Отсутствие проверки статуса в eWUŚ перед визитом к врачу", "Не добавление членов семьи к страховке трудоустроенного"]'::jsonb, '["Проверяйте статус в eWUŚ заранее", "Без страхового титула рассмотрите добровольное страхование или частный полис", "Уточните в ZUS процедуру добавления членов семьи"]'::jsonb, '["nfz.gov.pl", "zus.pl", "PUE ZUS"]'::jsonb, 'С 5 марта 2026 отменён спецзакон о безусловном бесплатном NFZ для украинцев со статусом UKR — взрослым нужен страховой титул; дети до 18, беременные и роженицы обслуживаются бесплатно.', 'медицина', 'service', NULL, NULL),
  ('Выбор семейного врача POZ', 'Podstawowa Opieka Zdrowotna — уровень первичной помощи: семейный врач, медсестра, акушерка, к которым приписываются по декларации выбора. Это точка входа в систему NFZ.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после оформления страховки в NFZ.', 'Лично в выбранной поликлинике (przychodnia) либо электронно через Internetowe Konto Pacjenta (IKP) на pacjent.gov.pl.', 'Поликлиники обычно 8:00-18:00; IKP — круглосуточно.', 'Не требуется запись, подача декларации в любое время.', '["Паспорт", "PESEL", "Подтверждение страхования в NFZ", "Заполненная декларация выбора врача", "Для оформления другого лица — доверенность/свидетельство о рождении"]'::jsonb, 'Первый выбор и до двух смен в год бесплатно; третья и последующая смена — 80 злотых (кроме переезда или прекращения работы врача).', 'Обычно вступает в силу сразу; при подаче через IKP — до 7 дней на подтверждение поликлиникой.', '["Убедитесь в наличии страховки NFZ", "Выберите поликлинику с договором NFZ", "Заполните деклаpацию лично или через IKP", "При электронной подаче подпишите Profil Zaufany", "Дождитесь подтверждения", "Аналогично выберите медсестру и акушерку"]'::jsonb, '["Ожидание, что смена врача требует согласия предыдущей поликлиники", "Использование третьей смены без понимания платности (80 злотых)", "Расхождение между бумажной и электронной декларацией"]'::jsonb, '["Проверяйте наличие договора поликлиники с NFZ на pacjent.gov.pl", "Смена при переезде не входит в лимит платных смен", "Отслеживайте статус поданной декларации в IKP"]'::jsonb, '["pacjent.gov.pl", "nfz.gov.pl"]'::jsonb, 'Подать декларацию можно и лично, и полностью электронно через IKP; правила платности смен (80 злотых с третьей) сохраняются.', 'медицина', 'service', NULL, NULL),
  ('Карта медстрахования EKUZ', 'Europejska Karta Ubezpieczenia Zdrowotnego — подтверждает право на необходимую по медпоказаниям бесплатную/льготную помощь при временном пребывании в других странах ЕС/ЕАСТ. Действует только за пределами Польши.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Заранее, до планируемой поездки в другую страну ЕС/ЕАСТ.', 'Воеводское отделение NFZ по месту жительства, лично, по почте, через ePUAP, IKP или email.', 'Обычно 8:00-16:00 в будни.', 'Не требуется для личной подачи; электронная заявка через IKP доступна круглосуточно.', '["Паспорт", "PESEL", "Подтверждение страхования в NFZ", "Заявление на выдачу EKUZ", "Справка U2 (для выезжающих на трудоустройство)", "Документы родства для членов семьи"]'::jsonb, 'Бесплатно.', 'До 3 рабочих дней для личной подачи и IKP.', '["Убедитесь в наличии страховки NFZ", "Выберите способ подачи (лично, ePUAP, IKP, email)", "Заполните заявление", "При IKP — подпишите и отправьте", "Дождитесь обработки (до 3 дней)", "Заберите карту или используйте электронный сертификат"]'::jsonb, '["Ожидание, что EKUZ покрывает любые услуги за границей", "Использование EKUZ вместо туристической страховки для длительных поездок", "Отсутствие проверки актуального страхового статуса перед подачей"]'::jsonb, '["Физически возить карту не обязательно — можно использовать электронный сертификат через IKP", "Проверяйте срок действия карты заранее", "Уточняйте у зарубежного медучреждения, работает ли оно в рамках госсистемы"]'::jsonb, '["nfz.gov.pl", "pacjent.gov.pl"]'::jsonb, 'Оформление доступно полностью онлайн через IKP; право на EKUZ напрямую зависит от актуального страхового статуса в NFZ.', 'медицина', 'service', NULL, NULL),
  ('Частная медицинская страховка', 'Платный полис от коммерческих поставщиков (LuxMed, Medicover, Enel-Med, PZU) с доступом к частным клиникам, коротким временем ожидания и обслуживанием на английском. Дополняет, но не заменяет обязательный NFZ.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В любой момент, часто сразу после переезда.', 'Напрямую у страховщика — сайт, приложение или офис продаж.', 'Офисы обычно 8:00/9:00-17:00/18:00; онлайн — круглосуточно.', 'Через сайт/приложение страховщика.', '["Паспорт", "PESEL (упрощает оформление, не всегда обязателен)", "Контактные данные", "Данные карты для оплаты"]'::jsonb, 'Medicover от ~30 злотых/мес. (базовый) до 150-300 злотых/мес.; LuxMed от ~100-150 до 300-500 злотых/мес.', 'От нескольких минут (онлайн) до 1-2 дней.', '["Сравните пакеты нескольких страховщиков", "Определите, нужен ли полис на семью", "Оформите заявку онлайн или в офисе", "Оплатите первый взнос", "Скачайте приложение страховщика", "Запишитесь на первый приём"]'::jsonb, '["Выбор самого дешёвого пакета без проверки нужных услуг", "Ожидание, что частная страховка полностью заменяет NFZ", "Игнорирование расположения сети клиник относительно дома/работы"]'::jsonb, '["Для семей часто выгоднее семейный пакет", "Проверьте среднее время ожидания к нужному специалисту в NFZ для сравнения", "Уточните корпоративные пакеты у работодателя — часто дешевле"]'::jsonb, '["luxmed.pl", "medicover.pl", "enel-med.pl", "pzu.pl"]'::jsonb, 'Среднее время ожидания к узким специалистам по NFZ остаётся долгим (месяцы), что поддерживает популярность частных страховок.', 'медицина', 'service', NULL, NULL),
  ('Обмен водительского удостоверения', 'Wymiana prawa jazdy — замена иностранных водительских прав на польские. Иностранное удостоверение действует в Польше только 6 месяцев с начала постоянного проживания, далее требуется обмен.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До истечения 6 месяцев с начала постоянного проживания.', 'Wydział Komunikacji местного управления — Urząd Miasta или Starostwo Powiatowe по месту регистрации/проживания.', 'Обычно 8:00-16:00/17:00 в будни.', 'Во многих городах доступна электронная запись.', '["Заявление на обмен", "Паспорт", "Карта побыту (при наличии)", "Оригинал прав и нотариально заверенная копия", "Нотариально заверенный перевод прав", "Фотография", "Медсправка и психотест (если требуется)"]'::jsonb, 'Госпошлина 100 злотых; регистрационный сбор 0,50 злотых; нотариальный перевод около 150 злотых.', 'Обычно несколько недель до месяца без экзаменов; с экзаменом — дольше.', '["Проверьте, входит ли страна в Венскую конвенцию 1968", "Соберите документы, включая заверенный перевод прав", "Запишитесь в Wydział Komunikacji", "Подайте заявление, оплатите сбор", "При необходимости пройдите медосмотр/экзамен", "Дождитесь обмена — иностранные права изымаются", "Получите польские права"]'::jsonb, '["Затягивание обмена сверх 6-месячного срока", "Подача без нотариально заверенного перевода", "Уверенность, что можно оставить иностранные права параллельно с польскими"]'::jsonb, '["Уточните в консульстве возможность замены просроченных прав перед обменом", "Записывайтесь заранее — очереди в крупных городах могут быть длинными", "Проверьте соответствие категории прав"]'::jsonb, '["сайты Urząd Miasta/Starostwo Powiatowe (Wydział Komunikacji)"]'::jsonb, 'Для украинцев права действительны до конца срока временной защиты, но при получении карты побыту обмен обязателен примерно через 185 дней проживания.', 'авто', 'service', NULL, NULL),
  ('Регистрация автомобиля', 'Rejestracja samochodu — обязательная постановка транспортного средства на учёт в Польше; выдаётся техпаспорт (dowód rejestracyjny) и номерные знаки.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В течение 30 дней после покупки автомобиля в Польше; налог PCC (2%) — в течение 14 дней при покупке у физлица.', 'Wydział Komunikacji по месту регистрации (мельдунка) или фактического проживания владельца.', 'Обычно 8:00-16:00/17:00 в будни.', 'Во многих городах доступна электронная запись.', '["Паспорт и карта побыту (или иной документ легальности)", "Договор купли-продажи или счёт-фактура", "Karta Pojazdu (если предусмотрена)", "Старые номерные знаки (для авто с пробегом)", "Действующий техосмотр", "Действующая страховка OC", "Подтверждение оплаты акциза/пошлины (для авто не из ЕС)", "Присяжный перевод иностранных документов"]'::jsonb, 'Регистрационный сбор около 160 злотых; налог PCC 2% от стоимости при покупке у физлица; акциз — для авто из-за пределов ЕС.', 'Временный техпаспорт часто сразу; постоянный — 2-3 недели.', '["Получите полный пакет от продавца", "Оформите страховку OC", "Пройдите техосмотр (если нужно)", "Оплатите налог PCC в течение 14 дней", "Для авто из-за границы оплатите акциз", "Подготовьте присяжные переводы", "Подайте заявление в Wydział Komunikacji в течение 30 дней", "Оплатите регистрационный сбор", "Получите техпаспорт"]'::jsonb, '["Пропуск 30-дневного срока регистрации после покупки", "Неучёт того, что техпаспорт иностранца привязан к сроку легального пребывания", "Отсутствие присяжного перевода иностранных документов"]'::jsonb, '["Уточните точный перечень документов на сайте вашего муниципалитета", "При продлении легализации сразу продлевайте техпаспорт", "Для авто из-за рубежа уточните у продавца, оплачен ли акциз"]'::jsonb, '["сайты Urząd Miasta/Starostwo Powiatowe (Wydział Komunikacji)", "podatki.gov.pl (KAS)"]'::jsonb, 'Регистрационный сбор около 160 злотых, налог PCC 2%, оплата в течение 14 дней; без карты побыту решение о постановке на учёт зависит от возможности определить срок допустимого пребывания.', 'авто', 'service', NULL, NULL),
  ('Страховка OC', 'Ubezpieczenie Odpowiedzialności Cywilnej — обязательная страховка гражданской ответственности владельца транспортного средства, покрывающая ущерб другим участникам движения. Обязательна для каждого зарегистрированного авто.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Не позднее дня регистрации автомобиля; перерыв в действии недопустим.', 'Онлайн на сайте страховщика, через агрегаторы сравнения цен, у агента или в отделении.', 'Онлайн — круглосуточно; отделения — 9:00-17:00/18:00.', 'Не требуется, оформление самостоятельное онлайн.', '["Техпаспорт автомобиля", "Паспорт или карта побыту", "Водительское удостоверение", "Справка о безаварийном стаже из другой страны с переводом (по желанию)"]'::jsonb, 'Индивидуальный расчёт (возраст, стаж, модель, регион, история); рассрочка увеличивает цену на 10-25%.', 'Оформляется практически мгновенно онлайн.', '["Подготовьте данные автомобиля и водителя", "Сравните предложения через агрегатор", "При наличии стажа из другой страны запросите справку с переводом", "Оформите полис онлайн и оплатите", "Сохраните электронную копию", "Убедитесь в отсутствии перерыва с предыдущим полисом"]'::jsonb, '["Допущение перерыва в страховании даже на один день", "Оформление после регистрации автомобиля вместо до/в день регистрации", "Выбор рассрочки без учёта переплаты"]'::jsonb, '["Уточните у страховщика, учитывается ли иностранный безаварийный стаж", "Сравнивайте предложения через агрегаторы", "Планируйте продление заранее"]'::jsonb, '["агрегаторы сравнения автостраховок в Польше"]'::jsonb, 'Минимальные страховые суммы около 29,9 млн злотых (жизнь/здоровье) и 6 млн злотых (имущество); штраф за перерыв — от 1920 до 9610 злотых в зависимости от длительности.', 'авто', 'service', NULL, NULL),
  ('Страховка AC', 'Autocasco — добровольная страховка, покрывающая ущерб или утрату собственного автомобиля: ДТП по своей вине, угон, вандализм, стихийные бедствия. Тарифы не регулируются государством.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В любой момент, часто одновременно с OC, особенно для нового/кредитного авто.', 'Онлайн на сайте страховщика, через агрегаторы, у агента или в отделении.', 'Онлайн — круглосуточно; отделения — 9:00-17:00/18:00.', 'Не требуется.', '["Техпаспорт автомобиля", "Паспорт или карта побыту", "Водительское удостоверение", "Осмотр/фото состояния кузова (для подержанных авто)", "История страховых случаев (при смене страховщика)"]'::jsonb, 'Не регулируется государством, ориентировочно от 2% от стоимости авто в год, зависит от франшизы.', 'От нескольких минут до часа; для подержанных авто — дольше из-за осмотра.', '["Оцените необходимость AC (новое/дорогое/кредитное авто)", "Сравните предложения через агрегатор", "Выберите размер франшизы", "Подготовьте документы", "При необходимости пройдите осмотр", "Оформите и оплатите полис"]'::jsonb, '["Оформление без изучения условий выплат", "Выбор минимальной франшизы без расчёта экономии", "Отсутствие уточнения условий при угоне"]'::jsonb, '["Сравнивайте предложения через агрегаторы — разброс цен большой", "Уточните скидку за непрерывную историю без выплат", "Проверьте условия франшизы для мелких повреждений"]'::jsonb, '["агрегаторы сравнения автостраховок в Польше"]'::jsonb, 'Тарифы по-прежнему не регулируются государством; AC часто оформляется вместе с OC, так как OC не покрывает собственный автомобиль владельца.', 'авто', 'service', NULL, NULL),
  ('Техосмотр', 'Badanie techniczne — обязательная периодическая проверка технического состояния автомобиля на станциях Stacje Kontroli Pojazdów. Результат вносится в свидетельство о регистрации.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Новые легковые — первый осмотр через 3 года, далее через 2 года, затем ежегодно; авто на газе и коммерческий транспорт — ежегодно.', 'Любая аккредитованная станция технического контроля, независимо от города регистрации.', 'Обычно 8:00-18:00 в будни, часть станций работает по субботам.', 'Обычно не требуется; часть операторов предлагает онлайн-запись.', '["Свидетельство о регистрации транспортного средства", "Паспорт или карта побыту", "Сертификат TDT для авто с газом", "Знак аварийной остановки и огнетушитель в салоне"]'::jsonb, 'Легковой автомобиль до 3,5 т — 149 злотых (2026); мотоцикл — 94 злотых; авто с LPG — около 245 злотых.', 'В день визита; при отрицательном результате — 14 дней на устранение и повторный осмотр.', '["Выберите аккредитованную станцию", "Приезжайте со свидетельством о регистрации", "Оплатите до начала осмотра", "Дождитесь проверки и фотофиксации", "При положительном результате — штамп с новой датой", "При отрицательном — устраните неисправности за 14 дней"]'::jsonb, '["Игнорирование срока действия техосмотра (штраф 1500-5000 злотых)", "Установка нелегальных LED-ламп без омологации", "Уверенность, что AC выплатит компенсацию так же, как OC, без техосмотра"]'::jsonb, '["Проходите осмотр за 30 дней до окончания срока", "Проверить срок можно бесплатно через сервис Mój Pojazd на mObywatel", "В зонах чистого транспорта строго проверяют сажевые фильтры/катализаторы"]'::jsonb, '["gov.pl (Министерство инфраструктуры)", "mObywatel (Mój Pojazd)", "Historia Pojazdu"]'::jsonb, 'Цены выросли впервые за 20+ лет и будут ежегодно индексироваться; введена обязательная фотофиксация автомобиля, хранится в CEPiK 10 лет.', 'авто', 'service', NULL, NULL),
  ('Договор аренды', 'Umowa najmu — письменное соглашение между владельцем и арендатором. Два основных типа: обычный umowa najmu и защищённый для арендодателя umowa najmu okazjonalnego (требует нотариального заявления арендатора).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед заселением, до передачи ключей и внесения залога.', 'Напрямую между сторонами или через агентство; для najem okazjonalny — нотариальное заверение заявления арендатора у любого нотариуса.', 'Не применимо; нотариальные конторы обычно 9:00-17:00.', 'Для najem okazjonalny рекомендуется запись к нотариусу.', '["Паспорт или карта побыту", "PESEL/NIP при наличии", "Справка о доходах/выписка со счёта (не всегда)", "Для najem okazjonalny — нотариально заверенное заявление о согласии на выселение", "Протокол передачи квартиры"]'::jsonb, 'Договор бесплатен; нотариальное заверение для najem okazjonalny — 100-300+ злотых; услуга предоставления запасного адреса — от 200-250 злотых.', 'Обычный договор — в день согласования; najem okazjonalny — дополнительно запись к нотариусу.', '["Проверьте право собственности через księga wieczysta", "Согласуйте условия", "Определите тип договора", "Внесите точные данные сторон и описание квартиры", "Подпишите договор в письменной форме", "Составьте протокол передачи", "Для najem okazjonalny — заверьте заявление у нотариуса", "Не переводите задаток до подписания"]'::jsonb, '["Перевод задатка до подписания договора", "Отсутствие проверки права собственности арендодателя", "Устная договорённость без письменного протокола передачи"]'::jsonb, '["Фиксируйте все платежи прямо в тексте договора", "Фотографируйте состояние квартиры и показания счётчиков при заселении", "Уточните срок уведомления о расторжении заранее"]'::jsonb, '["księga wieczysta (Министерство юстиции)"]'::jsonb, 'Около 80% арендодателей предпочитают najem okazjonalny; для отсутствующих собственного запасного адреса существуют платные сервисы предоставления такого адреса.', 'жильё', 'service', NULL, NULL),
  ('Регистрация адреса при аренде', 'Оформление мельдунка (zameldowanie) по адресу арендованного жилья на основании договора найма. Если имя арендатора указано в договоре, согласие собственника в ужонде не требуется.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Желательно сразу после подписания договора аренды, особенно перед подачей на PESEL/карту побыту.', 'Urząd Gminy/Dzielnicy (отдел ewidencji ludności) по месту нахождения квартиры, либо онлайн через gov.pl (Zamelduj się na pobyt czasowy) с Profil Zaufany.', 'Обычно 8:00-16:00/17:00; онлайн — круглосуточно.', 'Электронная запись на визит в части городов; полностью электронная регистрация через gov.pl с Profil Zaufany.', '["Загранпаспорт (с визой) или карта побыту", "Оригинал договора аренды с указанием имени арендатора", "Формуляр Zgłoszenie pobytu czasowego/stałego", "Подпись собственника (только если имени арендатора нет в договоре)"]'::jsonb, 'Бесплатно.', 'При личной подаче — сразу; онлайн — в течение нескольких дней.', '["Подпишите договор аренды с указанием вашего имени", "Скачайте формуляр с сайта гмины", "Заполните формуляр", "При отсутствии имени в договоре — получите подпись собственника", "Подайте лично или через gov.pl", "Получите подтверждение (zaświadczenie)"]'::jsonb, '["Ожидание письменного согласия собственника как обязательного условия при наличии имени в договоре", "Путаница между zameldowanie и постсоветской «пропиской»", "Регистрация на срок, превышающий срок легального основания пребывания"]'::jsonb, '["Уточняйте у арендодателя возможность мельдунка при поиске жилья", "Если имя в договоре — прописка возможна без подписи собственника", "Используйте электронную регистрацию через gov.pl при наличии Profil Zaufany"]'::jsonb, '["gov.pl (Zamelduj się na pobyt czasowy)", "сайты Urząd Gminy/Dzielnicy"]'::jsonb, 'Регистрацию можно оформить полностью онлайн через gov.pl с Profil Zaufany без визита в ужонд.', 'жильё', 'service', NULL, NULL),
  ('Коммунальные услуги', 'Складываются из чинша (czynsz — фиксированная административная плата) и платежей по счётчикам (media — вода, электричество, газ, отопление). Разделение платежей определяет владелец жилья.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Сразу после заселения — уточнить у арендодателя/администратора дома организацию оплаты.', 'Czynsz — собственнику или кооперативу; счётчики — поставщикам напрямую (PGE, Tauron, PGNiG) или в составе czynsz.', 'Офисы поставщиков обычно 8:00-17:00/18:00 в будни.', 'Для нового договора с поставщиком обычно не требуется, оформляется через сайт.', '["Паспорт или карта побыту", "Договор аренды (для переоформления счётчиков)", "Показания счётчиков на момент заселения (с фото)", "Реквизиты счёта для автооплаты"]'::jsonb, 'Ориентировочно: вода 8-11 злотых/куб.м, электричество ~0,7 злотых/кВт·ч, газ 1,5-1,6 злотых/куб.м; чинш в Варшаве ~700 злотых/мес.; вывоз мусора ~25-30 злотых с человека.', 'Переоформление счётчиков или новый договор — от нескольких дней до пары недель.', '["Уточните у арендодателя состав czynsz", "Зафиксируйте показания счётчиков при заселении (с фото)", "Уточните, на кого оформлены счётчики", "При необходимости заключите договор с поставщиком напрямую", "Настройте способ оплаты (по факту или авансом)", "Регулярно сверяйте показания", "При выезде зафиксируйте финальные показания"]'::jsonb, '["Отсутствие фиксации показаний при заселении и выезде", "Непонимание разницы между czynsz и платежами по счётчикам", "Ожидание единого стандарта коммунальных платежей по стране"]'::jsonb, '["Уточняйте точный состав czynsz заранее при выборе квартиры", "Города различаются по системе оплаты (авансовая/по счётчику)", "Уточните дату ежегодной сверки при авансовой системе"]'::jsonb, '["сайты поставщиков PGE, Tauron, PGNiG", "MOPS/MOPR (субсидии)"]'::jsonb, 'Средний czynsz за однокомнатную квартиру в Варшаве около 700 злотых/мес., сильно варьируется по регионам и домам.', 'жильё', 'service', NULL, NULL),
  ('Интернет и телефон', 'Подключение мобильной связи (SIM-карта) и домашнего интернета. Рынок контролируют четыре оператора — Play, Orange Polska, T-Mobile Polska и Plus (свыше 95% рынка, 4G/5G по всей стране).', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'SIM-карту — в первый день после приезда; домашний интернет — сразу после заселения в постоянное жильё.', 'Салоны операторов, магазины (Biedronka, Żabka) для SIM; сайт/офис провайдера для домашнего интернета.', 'Салоны в ТЦ обычно 9:00/10:00-20:00/21:00, включая выходные.', 'Обычно не требуется для SIM; для интернета иногда доступна онлайн-заявка с записью техника.', '["Паспорт или иной документ личности (для SIM)", "PESEL (не всегда, для контрактных тарифов чаще нужен)", "Договор аренды/адрес (для домашнего интернета)", "Банковская карта/реквизиты (для контрактных тарифов)"]'::jsonb, 'Мобильные тарифы от 25-35 злотых/мес. (пакетные) до полного безлимита дороже; предоплаченные звонки без тарифа — 0,29-0,79 злотых/мин.', 'SIM-карта — активация сразу; домашний интернет — от нескольких дней до 1-2 недель.', '["Выберите оператора (Play, Orange, T-Mobile, Plus)", "Купите SIM-карту с паспортом", "Активируйте и выберите тариф", "Для интернета выберите доступного провайдера", "Оформите заявку и согласуйте визит техника", "Проверьте скорость и сохраните договор"]'::jsonb, '["Выбор контрактного тарифа без PESEL/постоянного адреса", "Игнорирование условий пополнения на предоплаченных тарифах", "Подключение интернета без проверки доступности провайдера по адресу"]'::jsonb, '["Для коротких поездок выгоднее пакетный тариф", "Сравните покрытие операторов в вашем регионе", "Уточните условия роуминга по ЕС"]'::jsonb, '["play.pl", "orange.pl", "t-mobile.pl", "plus.pl"]'::jsonb, 'Plus и T-Mobile остаются наиболее доступными по безлимитным тарифам; поставщики обеспечивают 4G/5G почти по всей стране.', 'связь', 'service', NULL, NULL),
  ('SIM карта польская', 'Покупка и обязательная именная регистрация SIM-карты. С 2016 года анонимные SIM-карты (включая предоплаченные) в Польше не продаются.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'В любой момент, желательно в первые дни после приезда.', 'Салон оператора, точки Żabka, почта, виртуальные операторы (MVNO — Virgin Mobile, Mobile Vikings).', 'Салоны в ТЦ 9:00/10:00-20:00/21:00; точки Żabka часто круглосуточно.', 'Не требуется.', '["Паспорт (для взрослых старше 13 лет)", "PESEL (не всегда обязателен)", "Для несовершеннолетних до 13 — регистрирует родитель", "Для юрлица — NIP/REGON"]'::jsonb, 'Регистрация бесплатна; оплачивается только SIM-карта/тариф.', 'Активация в течение нескольких минут-часов после регистрации.', '["Выберите оператора или MVNO", "Приобретите SIM-карту", "Предоставьте паспорт для идентификации", "Заполните данные регистрации", "Дождитесь активации", "Выберите тариф", "Сохраните чек о покупке"]'::jsonb, '["Использование незарегистрированной SIM-карты (незаконно с 2016 года)", "Ожидание анонимной покупки без документов", "Незнание порядка перерегистрации старой SIM-карты на себя"]'::jsonb, '["Полученную от знакомых SIM-карту нужно перерегистрировать на своё имя", "У некоторых операторов доступна регистрация через интернет-банкинг", "Сравните обычных операторов и MVNO по тарифам"]'::jsonb, '["play.pl", "orange.pl", "t-mobile.pl", "plus.pl", "MSWiA (о законе о противодействии терроризму)"]'::jsonb, 'Обязательная именная регистрация действует с 2016 года без изменений; для регистрации достаточно паспорта, PESEL не обязателен.', 'связь', 'service', NULL, NULL),
  ('Перевод паспорта', 'Присяжный перевод паспорта на польский язык, выполненный переводчиком из реестра Минюста; принимается госучреждениями без дополнительного нотариального заверения.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Перед подачей документов, где требуется перевод паспорта (карта побыту, регистрация авто, отдельные заявления).', 'Напрямую у присяжного переводчика или бюро переводов; реестр — на сайте Минюста Польши.', 'Зависит от переводчика, обычно 9:00-17:00/18:00.', 'Часто не требуется, заказ дистанционно по сканам.', '["Оригинал паспорта (для сверки) или качественный скан/фото", "Апостиль на паспорт (если требуется для конкретной процедуры)"]'::jsonb, 'Официальный минимум для госзаказов от ~44 злотых/страница (английский); частные заказы обычно дороже, срочно — с доплатой.', '5-7 рабочих дней; срочно — 1-2 дня с доплатой.', '["Найдите присяжного переводчика нужного языка в реестре Минюста", "Отправьте скан на оценку", "Уточните формат получения (бумажный/электронный)", "Оплатите перевод", "Дождитесь готовности", "Приложите перевод к пакету документов"]'::jsonb, '["Заказ обычного, не присяжного перевода", "Путаница страницы A4 с расчётной страницей (1125 знаков)", "Незнание, что апостиль иногда должен предшествовать переводу"]'::jsonb, '["Для редких языков проверьте доступность переводчика в вашем городе заранее", "Печати и водяные знаки учитываются в объёме перевода", "Запрашивайте предварительную оценку по скану бесплатно"]'::jsonb, '["arch-bip.ms.gov.pl (реестр присяжных переводчиков)"]'::jsonb, 'Официальные минимальные ставки от 16.10.2023 остаются ориентиром в 2026 году; расчётная единица — 1125 знаков, а не физический лист.', 'документы', 'service', NULL, NULL),
  ('Апостиль на паспорт', 'Международный штамп, подтверждающий подлинность документа для стран — участниц Гаагской конвенции 1961 года. Ставится в стране происхождения, обычно на нотариальную копию паспорта, а не на оригинал.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'Заранее, до переезда в Польшу или во время визита на родину.', 'Уполномоченный орган страны происхождения (Минюст/МИД); если уже в Польше без апостиля — консульство своей страны в Польше.', 'Зависит от органа в вашей стране.', 'В некоторых странах доступна электронная запись/e-Apostille.', '["Оригинал паспорта (для нотариальной копии, если апостиль не ставится на оригинал)", "Нотариально заверенная копия паспорта", "Квитанция об оплате пошлины"]'::jsonb, 'Зависит от страны — госпошлина плюс нотариальное заверение копии.', 'От нескольких дней до пары недель; срочно — быстрее за доплату.', '["Уточните, действительно ли нужен апостиль для процедуры в Польше", "Проверьте, ставится ли апостиль на оригинал или нужна нотариальная копия", "Оформите нотариальную копию при необходимости", "Подайте на апостилирование в компетентный орган", "Оплатите пошлину", "Получите документ с апостилем", "При необходимости закажите присяжный перевод уже в Польше"]'::jsonb, '["Попытка поставить апостиль в Польше вместо страны происхождения", "Ожидание, что апостиль можно поставить на оригинал паспорта", "Оформление апостиля без проверки, действительно ли он нужен"]'::jsonb, '["Уточняйте требования заранее в польском учреждении, куда подаёте документы", "Если уже в Польше — узнайте в консульстве своей страны о содействии", "Планируйте апостилирование заранее, до переезда"]'::jsonb, '["Минюст/МИД вашей страны", "консульство вашей страны в Польше"]'::jsonb, 'Список стран — участниц Гаагской конвенции расширяется (напр. Алжир с июля 2026); апостиль всегда ставится в стране происхождения документа.', 'документы', 'service', NULL, NULL),
  ('Нотариальные услуги', 'Заверение подписи, доверенности, акты купли-продажи, договоры najem okazjonalny, завещания и другие юридически значимые документы у нотариуса (notariusz). Максимальные тарифы регулирует Минюст Польши.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'По мере необходимости конкретной сделки (доверенность, аренда, недвижимость, регистрация бизнеса).', 'Любая нотариальная контора (kancelaria notarialna) в любом городе — привязки к месту жительства нет.', 'Обычно 9:00-17:00 в будни.', 'Рекомендуется предварительная запись по телефону/сайту, особенно для сложных сделок.', '["Паспорт или карта побыту", "PESEL (при наличии)", "Документы по конкретной сделке", "Присяжный перевод документов не на польском"]'::jsonb, 'Ориентировочно (2026): заверение подписи ~20-60 злотых; доверенность на одно действие 30-100 злотых; завещание от 50-200 злотых (плюс НДС 23%).', 'Простые действия — в день визита; сложные сделки — от нескольких дней до пары недель.', '["Определите нужную нотариальную услугу", "Выберите контору, сравнив условия", "Запишитесь на приём", "Придите с оригиналами документов и переводом при необходимости", "Оплатите нотариальный сбор", "Получите готовый документ"]'::jsonb, '["Ожидание одинаковой цены у всех нотариусов — таксы максимальные, а не фиксированные", "Приход без присяжного перевода документов не на польском", "Путаница между видами доверенностей"]'::jsonb, '["Используйте калькуляторы нотариальных такс для предварительной оценки", "Уточняйте типовые цены по телефону заранее", "При выезде нотариуса вне конторы уточните доплату за выезд"]'::jsonb, '["реестр нотариальных контор Польши"]'::jsonb, 'В 2026 обсуждается и частично происходит повышение ряда максимальных нотариальных такс — уточняйте актуальные тарифы у нотариуса на момент обращения.', 'документы', 'service', NULL, NULL),
  ('Страховка путешественника', 'Медицинская страховка, покрывающая расходы во время поездки в Польшу до получения постоянной страховки NFZ. Для визы D требуется покрытие не менее 30 000 евро.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До отъезда из своей страны; для визы D оформляется заранее и прикладывается к пакету документов.', 'Онлайн через страховые компании/агрегаторы (cherehapa.ru, sravni.ru, greentravel.ua, safetywing.com), без визита.', 'Онлайн — круглосуточно, полис приходит за 5-15 минут.', 'Полностью онлайн.', '["Загранпаспорт", "Email для получения полиса", "Банковская карта для оплаты"]'::jsonb, 'Покрытие 30 000 € на 1 месяц — 5-15 €; 50 000 € на 1 месяц — 10-25 €; 30 000 € на год — 50-100 €.', 'Полис приходит за 5-15 минут; вступает в силу на следующий день или в указанную дату.', '["Зайдите на агрегатор страховок", "Укажите Польшу/зону Шенген и даты поездки", "Укажите данные путешественника", "Выберите тариф с покрытием от 30 000 €", "Оплатите онлайн", "Получите полис на email", "Приложите к пакету документов на визу"]'::jsonb, '["Оформление страховки только на Польшу вместо всего Шенгена", "Покрытие меньше 30 000 € — консульство отказывает", "Страховка на даты поездки, но не на весь срок визы"]'::jsonb, '["Для визы D берите покрытие 50 000 € — консульства лояльнее", "Годовая мультивизовая страховка выгоднее при нескольких поездках", "После официального трудоустройства NFZ заменяет страховку путешественника"]'::jsonb, '["cherehapa.ru", "sravni.ru", "greentravel.ua", "safetywing.com"]'::jsonb, 'Для визы D обязательное покрытие минимум 30 000 € на весь Шенген; граждане ЕС используют бесплатную карту EKUZ вместо отдельной страховки.', 'медицина', 'service', NULL, NULL),
  ('Медицинская справка для визы', 'Документ о состоянии здоровья, требуется в отдельных случаях: для медицинских работников, при оформлении медицинской визы для лечения, либо по отдельному запросу консульства. Для стандартной рабочей/студенческой визы D обычно не нужна.', '{"UA": true, "MD": true, "GE": true, "AM": true, "BY": true, "RU": true, "UZ": true, "TJ": true, "KZ": true, "KG": true, "TM": true, "AZ": true, "TR": true, "DE": true, "FR": true, "IT": true, "ES": true, "NL": true, "BE": true, "AT": true, "SE": true, "DK": true, "FI": true, "CZ": true, "SK": true, "HU": true, "RO": true, "BG": true, "HR": true, "GR": true, "PT": true, "LT": true, "LV": true, "EE": true, "US": true, "CA": true, "AU": true, "JP": true, "IL": true, "KR": true, "NO": true, "CH": true, "GB": true}'::jsonb, 'До отъезда, если справка требуется — уточните в консульстве заранее.', 'Медицинское учреждение своей страны (терапевт, поликлиника, частная клиника); для медработников — дополнительно приглашение от польского работодателя.', 'Зависит от медучреждения вашей страны.', 'Зависит от учреждения, часто по телефону или онлайн.', '["Паспорт", "Направление от работодателя (если для работы)", "Для медработников — диплом, приглашение от польского работодателя, документ о квалификации", "Перевод справки на польский у присяжного переводчика (для визы)"]'::jsonb, 'В госполиклинике бесплатно или 5-20 €; в частной клинике 20-50 €; перевод у присяжного переводчика 30-80 €.', 'Оформление справки 1-3 дня; перевод 1-5 дней; срок действия справки обычно 3-6 месяцев.', '["Уточните в консульстве, нужна ли именно вам справка", "Обратитесь к врачу-терапевту", "Получите справку о состоянии здоровья", "Переведите справку у присяжного переводчика", "При необходимости поставьте апостиль", "Приложите к пакету документов на визу"]'::jsonb, '["Получение справки заблаговременно — теряет срок действия", "Отсутствие перевода у присяжного переводчика", "Медработники не уточняют требования конкретного польского работодателя"]'::jsonb, '["Уточните в консульстве точный список требований к справке", "Для стандартной визы D справка обычно не нужна — только страховка", "Медработникам заранее уточнить требуемую справку у польского работодателя"]'::jsonb, '["сайт консульства Польши в вашей стране", "gov.pl"]'::jsonb, 'Для стандартной визы D справка в большинстве случаев не требуется; для медработников требования ужесточились — нужна справка о профпригодности от польского врача по труду.', 'медицина', 'service', NULL, NULL);